import React, { useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuthStore } from '../../store/authStore';
import { Shield, Mail, Lock, Eye, EyeOff, AlertCircle, Loader2, Github } from 'lucide-react';

export function LoginPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const callbackUrl = searchParams.get('callback') || '/dashboard';
  const { login, ssoLogin } = useAuthStore();

  const [formData, setFormData] = useState({ email: '', password: '' });
  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const validate = () => {
    const newErrors = {};
    if (!formData.email) newErrors.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) newErrors.email = 'Invalid email format';
    if (!formData.password) newErrors.password = 'Password is required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    setIsLoading(true);
    setError('');

    const result = await login(formData.email, formData.password);
    if (result.success) {
      navigate(callbackUrl, { replace: true });
    } else {
      setError(result.error || 'Login failed');
    }
    setIsLoading(false);
  };

  const handleSSOLogin = (provider) => {
    ssoLogin(provider);
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <div className="auth-header">
          <Link to="/" className="auth-logo">
            <div className="navbar-logo-placeholder">G</div>
            <span>Gatekeeper</span>
          </Link>
          <h1>Welcome back</h1>
          <p>Sign in to access your phishing protection dashboard</p>
        </div>

        {error && (
          <div className="auth-error" role="alert">
            <AlertCircle size={18} />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="auth-form" noValidate>
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <div className="input-wrapper">
              <Mail size={18} className="input-icon" />
              <input
                id="email"
                type="email"
                name="email"
                value={formData.email}
                onChange={e => setFormData({ ...formData, email: e.target.value })}
                placeholder="you@company.com"
                autoComplete="email"
                disabled={isLoading}
                aria-invalid={!!errors.email}
                aria-describedby={errors.email ? 'email-error' : undefined}
              />
            </div>
            {errors.email && <span id="email-error" className="field-error">{errors.email}</span>}
          </div>

          <div className="form-group">
            <div className="form-group-header">
              <label htmlFor="password">Password</label>
              <Link to="/forgot-password" className="forgot-link">Forgot password?</Link>
            </div>
            <div className="input-wrapper">
              <Lock size={18} className="input-icon" />
              <input
                id="password"
                type={showPassword ? 'text' : 'password'}
                name="password"
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
                placeholder="••••••••"
                autoComplete="current-password"
                disabled={isLoading}
                aria-invalid={!!errors.password}
                aria-describedby={errors.password ? 'password-error' : undefined}
              />
              <button
                type="button"
                className="toggle-password"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
            {errors.password && <span id="password-error" className="field-error">{errors.password}</span>}
          </div>

          <button type="submit" className="btn btn-primary btn-block btn-lg" disabled={isLoading}>
            {isLoading ? (
              <>
                <Loader2 size={18} className="spinner" />
                Signing in...
              </>
            ) : (
              'Sign In'
            )}
          </button>
        </form>

        <div className="auth-divider">
          <span>or continue with</span>
        </div>

        <div className="auth-sso">
          <button
            type="button"
            className="btn btn-sso btn-microsoft"
            onClick={() => handleSSOLogin('microsoft')}
            disabled={isLoading}
          >
            <svg width={20} height={20} viewBox="0 0 24 24" fill="currentColor">
              <path d="M19.2 16.83c-.31.12-.61.12-.92 0-1.6-.67-4.03-.69-5.39-.01-.35.17-.76.48-1.11.91-.3.37-.58.77-.82 1.2-.64 1.14-1.8 2.73-3.46 2.73-1.66 0-2.82-1.59-2.82-3.92 0-2.33 1.16-3.92 2.82-3.92 1.75 0 2.85 1.65 3.37 2.86.12.26.35.54.66.54.58 0 .96-.7.83-1.34-.14-.6-.38-1.16-.7-1.7-.66-1.03-1.64-1.51-2.76-1.51-2.08 0-4.06 2.09-4.06 5.55 0 1.45.42 2.7 1.04 3.73-.45.05-.89.13-1.33.19v.85h-1.8v-4.1h-1.8v9h2.7c.57 1.1 1.58 1.9 3.15 1.9 2.65 0 4.06-2.14 4.06-4.93.01-.74-.11-1.39-.28-1.96.45-.09.9-.22 1.34-.39zM7.43 12.05c0-2.08 1.31-3.25 3.17-3.25 1.8 0 3.12 1.08 3.12 3.25s-1.32 3.26-3.12 3.26c-1.86 0-3.17-1.18-3.17-3.26z" />
            </svg>
            <span>Microsoft Entra ID</span>
          </button>
        </div>

        <p className="auth-footer">
          Don't have an account? <Link to="/register">Create one</Link>
        </p>
      </div>
    </div>
  );
}