import React from 'react';
import { Link, useLocation, NavLink } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { Menu, X, Shield, LayoutDashboard, Users, Settings, LogOut, User, ChevronDown, ChevronRight, Monitor, Activity, Key, Building2 } from 'lucide-react';

export function Navbar({ onMenuClick }) {
  const { user, isAuthenticated, logout } = useAuthStore();
  const location = useLocation();
  const [showUserMenu, setShowUserMenu] = React.useState(false);

  const handleLogout = async () => {
    await logout();
    setShowUserMenu(false);
  };

  return (
    <nav className="navbar" role="navigation" aria-label="Main navigation">
      <div className="navbar-left">
        <button className="menu-btn" onClick={onMenuClick} aria-label="Toggle menu">
          <Menu size={20} />
        </button>
        <Link to="/" className="navbar-brand" aria-label="Gatekeeper Home">
          <div className="navbar-logo-placeholder">G</div>
          <span className="navbar-name">Gatekeeper</span>
        </Link>
      </div>

      <div className="navbar-center">
        {isAuthenticated && (
          <>
            <NavLink to="/dashboard" className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}>
              <LayoutDashboard size={16} /> Dashboard
            </NavLink>
            {user?.role === 'super_admin' && (
              <NavLink to="/admin" className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}>
                <Shield size={16} /> Admin
              </NavLink>
            )}
            {user?.role === 'org_admin' && user?.memberships?.some(m => m.role === 'admin' || m.role === 'owner') && (
              <NavLink to="/org-admin" className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}>
                <Building2 size={16} /> Org Admin
              </NavLink>
            )}
          </>
        )}
      </div>

      <div className="navbar-right">
        {isAuthenticated ? (
          <div className="user-menu" onMouseEnter={() => setShowUserMenu(true)} onMouseLeave={() => setShowUserMenu(false)}>
            <button className="user-avatar-btn" onClick={() => setShowUserMenu(!showUserMenu)} aria-expanded={showUserMenu} aria-haspopup="true">
              <div className="user-avatar">{user?.first_name?.[0]}{user?.last_name?.[0]}</div>
              <ChevronDown size={14} />
            </button>
            {showUserMenu && (
              <div className="user-dropdown">
                <div className="user-dropdown-header">
                  <span className="user-dropdown-name">{user?.first_name} {user?.last_name}</span>
                  <span className="user-dropdown-email">{user?.email}</span>
                  <span className={`role-badge ${user?.role}`}>{user?.role?.replace('_', ' ')}</span>
                </div>
                <NavLink to="/account" onClick={() => setShowUserMenu(false)} className="dropdown-item">
                  <User size={16} /> Account
                </NavLink>
                <NavLink to="/scans" onClick={() => setShowUserMenu(false)} className="dropdown-item">
                  <Activity size={16} /> Scan History
                </NavLink>
                {user?.role === 'org_admin' && (
                  <NavLink to="/org-admin" onClick={() => setShowUserMenu(false)} className="dropdown-item">
                    <Building2 size={16} /> Organization Admin
                  </NavLink>
                )}
                {user?.role === 'super_admin' && (
                  <NavLink to="/admin" onClick={() => setShowUserMenu(false)} className="dropdown-item">
                    <Shield size={16} /> Super Admin
                  </NavLink>
                )}
                <div className="dropdown-divider" />
                <button onClick={handleLogout} className="dropdown-item danger">
                  <LogOut size={16} /> Logout
                </button>
              </div>
            )}
          </div>
        ) : (
          <div className="auth-buttons">
            <Link to="/login" className="btn btn-ghost">Login</Link>
            <Link to="/register" className="btn btn-primary">Get Started</Link>
          </div>
        )}
      </div>
    </nav>
  );
}

export function Sidebar({ isOpen, onClose }) {
  const { user, isAuthenticated } = useAuthStore();
  const location = useLocation();

  const navItems = [
    { path: '/dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: ['user', 'org_admin', 'super_admin'] },
    { path: '/scans', label: 'Scan History', icon: Activity, roles: ['user', 'org_admin', 'super_admin'] },
    { path: '/account', label: 'Account', icon: User, roles: ['user', 'org_admin', 'super_admin'] },
    { path: '/extension', label: 'Extension', icon: Monitor, roles: ['user', 'org_admin', 'super_admin'] },
    { path: '/org-admin', label: 'Org Admin', icon: Building2, roles: ['org_admin', 'super_admin'] },
    { path: '/admin', label: 'Super Admin', icon: Shield, roles: ['super_admin'] }
  ];

  const filteredItems = isAuthenticated
    ? navItems.filter(item => item.roles.includes(user?.role))
    : [];

  return (
    <>
      {isOpen && <div className="sidebar-overlay" onClick={onClose} />}
      <aside className={`sidebar ${isOpen ? 'open' : ''}`} role="navigation" aria-label="Sidebar navigation">
        <div className="sidebar-header">
          <Link to="/" className="sidebar-brand">
            <div className="navbar-logo-placeholder">G</div>
            <span>Gatekeeper</span>
          </Link>
          <button className="sidebar-close" onClick={onClose} aria-label="Close sidebar">
            <X size={20} />
          </button>
        </div>
        <nav className="sidebar-nav">
          {filteredItems.map(item => (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
              onClick={onClose}
            >
              <item.icon size={18} />
              <span>{item.label}</span>
            </NavLink>
          ))}
          {!isAuthenticated && (
            <div className="sidebar-auth">
              <Link to="/login" className="sidebar-link" onClick={onClose}>
                <Key size={18} /> Login
              </Link>
              <Link to="/register" className="sidebar-link btn-primary" onClick={onClose}>
                <Shield size={18} /> Get Started
              </Link>
            </div>
          )}
        </nav>
      </aside>
    </>
  );
}

export function PageLayout({ children, title }) {
  const [sidebarOpen, setSidebarOpen] = React.useState(false);

  return (
    <div className="page-layout">
      <Navbar onMenuClick={() => setSidebarOpen(true)} />
      <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <main className="main-content" role="main">
        {title && (
          <header className="page-header">
            <h1 className="page-title">{title}</h1>
          </header>
        )}
        <div className="page-content">{children}</div>
      </main>
    </div>
  );
}

export function PublicLayout({ children }) {
  const [sidebarOpen, setSidebarOpen] = React.useState(false);

  return (
    <div className="public-layout">
      <Navbar onMenuClick={() => setSidebarOpen(true)} />
      <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <main className="public-main" role="main">
        {children}
      </main>
    </div>
  );
}