import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuthStore } from '../../store/authStore';
import { Shield, Mail, AlertCircle, Loader2, CheckCircle, ArrowLeft } from 'lucide-react';

export function ForgotPasswordPage() {
  const navigate = useNavigate();
  const { forgotPassword } = useAuthStore();

  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email) {
      setError('Email is required');
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError('Invalid email format');
      return;
    }

    setIsLoading(true);
    setError('');

    const result = await forgotPassword(email);
    if (result.success) {
      setSubmitted(true);
    } else {
      setError('Failed to send reset email');
    }
    setIsLoading(false);
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <div className="auth-header">
          <Link to="/login" className="back-link">
            <ArrowLeft size={18} />
            <span>Back to login</span>
          </Link>
          <div className="auth-logo">
            <div className="navbar-logo-placeholder">G</div>
            <span>Gatekeeper</span>
          </div>
          <h1>{submitted ? 'Check your email' : 'Forgot password?'}</h1>
          <p>{submitted
            ? 'If an account exists, you\'ll receive a password reset link shortly.'
            : 'Enter your email and we\'ll send you a link to reset your password.'}</p>
        </div>

        {!submitted && (
          <form onSubmit={handleSubmit} className="auth-form" noValidate>
            {error && (
              <div className="auth-error" role="alert">
                <AlertCircle size={18} />
                <span>{error}</span>
              </div>
            )}

            <div className="form-group">
              <label htmlFor="email">Email</label>
              <div className="input-wrapper">
                <Mail size={18} className="input-icon" />
                <input
                  id="email"
                  type="email"
                  name="email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  placeholder="you@company.com"
                  autoComplete="email"
                  disabled={isLoading}
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary btn-block btn-lg" disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 size={18} className="spinner" />
                  Sending...
                </>
              ) : (
                'Send Reset Link'
              )}
            </button>
          </form>
        )}

        {submitted && (
          <div className="auth-success">
            <div className="success-icon"><CheckCircle size={48} /></div>
            <h2>Email sent!</h2>
            <p>If an account with that email exists, you'll receive a password reset link within a few minutes.</p>
            <Link to="/login" className="btn btn-primary btn-block">Back to Login</Link>
          </div>
        )}

        <p className="auth-footer">
          Remember your password? <Link to="/login">Sign in</Link>
        </p>
      </div>
    </div>
  );
}