import { create } from 'zustand';

export const useAdminStore = create((set, get) => ({
  dashboard: null,
  allUsers: [],
  allOrgs: [],
  allActivity: [],
  globalStats: null,
  isLoading: false,
  error: null,

  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),

  loadDashboard: async () => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.admin.dashboard();
      set({ dashboard: data, isLoading: false });
      return data;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  loadUsers: async (params = {}) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.admin.users.list(params);
      set({ allUsers: data.users, isLoading: false });
      return data;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  createUser: async (data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.admin.users.create(data);
      set(state => ({ allUsers: [result.user, ...state.allUsers] }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  updateUser: async (id, data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.admin.users.update(id, data);
      set(state => ({
        allUsers: state.allUsers.map(u => u.id === id ? result.user : u)
      }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  deleteUser: async (id) => {
    try {
      const { api } = require('../services/api');
      await api.admin.users.delete(id);
      set(state => ({ allUsers: state.allUsers.filter(u => u.id !== id) }));
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadOrgs: async (params = {}) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.admin.organizations.list(params);
      set({ allOrgs: data.organizations, isLoading: false });
      return data;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  createOrg: async (data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.admin.organizations.create(data);
      set(state => ({ allOrgs: [result.organization, ...state.allOrgs] }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  updateOrg: async (id, data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.admin.organizations.update(id, data);
      set(state => ({
        allOrgs: state.allOrgs.map(o => o.id === id ? result.organization : o)
      }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  deleteOrg: async (id) => {
    try {
      const { api } = require('../services/api');
      await api.admin.organizations.delete(id);
      set(state => ({ allOrgs: state.allOrgs.filter(o => o.id !== id) }));
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadActivity: async (params = {}) => {
    try {
      const { api } = require('../services/api');
      const data = await api.admin.activity(params);
      set({ allActivity: data.activity });
      return data;
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadStats: async () => {
    try {
      const { api } = require('../services/api');
      const data = await api.admin.stats();
      set({ globalStats: data });
      return data;
    } catch (e) {
      set({ error: e.message });
    }
  }
}));