import React, { useState, useEffect } from 'react';
import { useAuthStore } from '../../store/authStore';
import { useScanStore } from '../../store/scanStore';
import { useOrgStore } from '../../store/orgStore';
import { User, Mail, Lock, Shield, Monitor, Key, Loader2, CheckCircle, AlertCircle, Eye, EyeOff, Trash2, Settings, LogOut } from 'lucide-react';

export function AccountPage() {
  const { user, updateProfile, changePassword, logout, linkExtension, unlinkExtension, getExtensionStatus } = useAuthStore();
  const { loadHistory } = useScanStore();
  const { loadOrgs } = useOrgStore();

  const [activeTab, setActiveTab] = useState('profile');
  const [profileData, setProfileData] = useState({ firstName: '', lastName: '' });
  const [passwordData, setPasswordData] = useState({ current: '', new: '', confirm: '' });
  const [extensionLinked, setExtensionLinked] = useState(false);
  const [extensionToken, setExtensionToken] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  useEffect(() => {
    if (user) {
      setProfileData({ firstName: user.first_name, lastName: user.last_name });
      setExtensionLinked(!!user.extension_token);
    }
    getExtensionStatus().then(data => {
      setExtensionLinked(data.linked);
    });
  }, [user]);

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setSuccess('');
    try {
      const result = await updateProfile(profileData);
      if (result.success) {
        setSuccess('Profile updated successfully');
      } else {
        setError(result.error || 'Failed to update profile');
      }
    } catch (e) {
      setError('Failed to update profile');
    }
    setIsLoading(false);
  };

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    if (passwordData.new !== passwordData.confirm) {
      setError('New passwords do not match');
      return;
    }
    if (passwordData.new.length < 8) {
      setError('Password must be at least 8 characters');
      return;
    }
    setIsLoading(true);
    setError('');
    setSuccess('');
    try {
      const result = await changePassword(passwordData.current, passwordData.new);
      if (result.success) {
        setSuccess('Password changed successfully');
        setPasswordData({ current: '', new: '', confirm: '' });
      } else {
        setError(result.error || 'Failed to change password');
      }
    } catch (e) {
      setError('Failed to change password');
    }
    setIsLoading(false);
  };

  const handleLinkExtension = async () => {
    setIsLoading(true);
    setError('');
    try {
      const result = await linkExtension();
      if (result.success) {
        setExtensionToken(result.token);
        setExtensionLinked(true);
        setSuccess('Extension linked! Copy the token below and paste it in the extension settings.');
      } else {
        setError(result.error || 'Failed to link extension');
      }
    } catch (e) {
      setError('Failed to link extension');
    }
    setIsLoading(false);
  };

  const handleUnlinkExtension = async () => {
    if (!window.confirm('Unlink the browser extension? You\'ll need to relink to use it with your account.')) return;
    setIsLoading(true);
    try {
      const result = await unlinkExtension();
      if (result.success) {
        setExtensionLinked(false);
        setExtensionToken('');
        setSuccess('Extension unlinked');
      } else {
        setError('Failed to unlink extension');
      }
    } catch (e) {
      setError('Failed to unlink extension');
    }
    setIsLoading(false);
  };

  const handleLogout = async () => {
    await logout();
  };

  const tabs = [
    { id: 'profile', label: 'Profile', icon: User },
    { id: 'security', label: 'Security', icon: Shield },
    { id: 'extension', label: 'Extension', icon: Monitor },
    { id: 'danger', label: 'Danger Zone', icon: AlertCircle }
  ];

  return (
    <div className="account-page">
      <div className="page-header">
        <div>
          <h1>Account Settings</h1>
          <p>Manage your profile, security, and connected services</p>
        </div>
      </div>

      <div className="account-layout">
        <nav className="account-nav">
          {tabs.map(tab => (
            <button
              key={tab.id}
              className={`account-nav-item ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              <tab.icon size={18} />
              <span>{tab.label}</span>
            </button>
          ))}
        </nav>

        <div className="account-content">
          {error && <div className="alert error"><AlertCircle size={18} /> {error}</div>}
          {success && <div className="alert success"><CheckCircle size={18} /> {success}</div>}

          {activeTab === 'profile' && (
            <form onSubmit={handleProfileUpdate} className="account-form">
              <h2>Profile Information</h2>
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="firstName">First Name</label>
                  <input
                    id="firstName"
                    type="text"
                    value={profileData.firstName}
                    onChange={e => setProfileData({ ...profileData, firstName: e.target.value })}
                    disabled={isLoading}
                  />
                </div>
                <div className="form-group">
                  <label htmlFor="lastName">Last Name</label>
                  <input
                    id="lastName"
                    type="text"
                    value={profileData.lastName}
                    onChange={e => setProfileData({ ...profileData, lastName: e.target.value })}
                    disabled={isLoading}
                  />
                </div>
              </div>
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  type="email"
                  value={user?.email}
                  disabled
                  className="disabled-input"
                />
                <span className="form-hint">Email cannot be changed. Contact support if needed.</span>
              </div>
              <div className="form-group">
                <label>Role</label>
                <div className="role-badge-display">
                  <span className={`role-badge ${user?.role}`}>{user?.role?.replace('_', ' ')}</span>
                </div>
              </div>
              <button type="submit" className="btn btn-primary" disabled={isLoading}>
                {isLoading ? 'Saving...' : 'Save Changes'}
              </button>
            </form>
          )}

          {activeTab === 'security' && (
            <form onSubmit={handlePasswordChange} className="account-form">
              <h2>Change Password</h2>
              <div className="form-group">
                <label htmlFor="currentPassword">Current Password</label>
                <div className="input-wrapper">
                  <Lock size={18} className="input-icon" />
                  <input
                    id="currentPassword"
                    type={showCurrentPassword ? 'text' : 'password'}
                    value={passwordData.current}
                    onChange={e => setPasswordData({ ...passwordData, current: e.target.value })}
                    autoComplete="current-password"
                    disabled={isLoading}
                  />
                  <button type="button" className="toggle-password" onClick={() => setShowCurrentPassword(!showCurrentPassword)}>
                    {showCurrentPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>
              <div className="form-group">
                <label htmlFor="newPassword">New Password</label>
                <div className="input-wrapper">
                  <Lock size={18} className="input-icon" />
                  <input
                    id="newPassword"
                    type={showNewPassword ? 'text' : 'password'}
                    value={passwordData.new}
                    onChange={e => setPasswordData({ ...passwordData, new: e.target.value })}
                    autoComplete="new-password"
                    disabled={isLoading}
                  />
                  <button type="button" className="toggle-password" onClick={() => setShowNewPassword(!showNewPassword)}>
                    {showNewPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                <div className="password-requirements">
                  <span className={passwordData.new.length >= 8 ? 'met' : 'unmet'}><CheckCircle size={12} /> At least 8 characters</span>
                  <span className={/[A-Z]/.test(passwordData.new) ? 'met' : 'unmet'}><CheckCircle size={12} /> One uppercase</span>
                  <span className={/[a-z]/.test(passwordData.new) ? 'met' : 'unmet'}><CheckCircle size={12} /> One lowercase</span>
                  <span className={/[0-9]/.test(passwordData.new) ? 'met' : 'unmet'}><CheckCircle size={12} /> One number</span>
                  <span className={/[^A-Za-z0-9]/.test(passwordData.new) ? 'met' : 'unmet'}><CheckCircle size={12} /> One special char</span>
                </div>
              </div>
              <div className="form-group">
                <label htmlFor="confirmPassword">Confirm New Password</label>
                <div className="input-wrapper">
                  <Lock size={18} className="input-icon" />
                  <input
                    id="confirmPassword"
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={passwordData.confirm}
                    onChange={e => setPasswordData({ ...passwordData, confirm: e.target.value })}
                    autoComplete="new-password"
                    disabled={isLoading}
                  />
                  <button type="button" className="toggle-password" onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                    {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                {passwordData.confirm && passwordData.new !== passwordData.confirm && (
                  <span className="field-error">Passwords do not match</span>
                )}
              </div>
              <button type="submit" className="btn btn-primary" disabled={isLoading}>
                {isLoading ? 'Changing...' : 'Change Password'}
              </button>
            </form>
          )}

          {activeTab === 'extension' && (
            <div className="account-form">
              <h2>Browser Extension</h2>
              <p className="section-desc">Link the Gatekeeper browser extension to your account for seamless scan history sync and personalized protection.</p>

              <div className="extension-status-card">
                <div className="extension-status-header">
                  <div className={`status-indicator ${extensionLinked ? 'connected' : 'disconnected'}`} />
                  <div>
                    <h3>{extensionLinked ? 'Extension Linked' : 'Extension Not Linked'}</h3>
                    <p>{extensionLinked ? 'Your extension is connected and syncing scans' : 'Link the extension to sync scan history and settings'}</p>
                  </div>
                </div>

                {extensionLinked ? (
                  <div className="extension-linked-actions">
                    <div className="extension-token">
                      <label>Extension Token</label>
                      <div className="token-display">
                        <code>{extensionToken || '••••••••••••••••'}</code>
                        <button className="btn btn-sm btn-secondary" onClick={() => navigator.clipboard.writeText(extensionToken)}>
                          Copy
                        </button>
                      </div>
                      <p className="form-hint">Keep this token secret. Anyone with it can link their extension to your account.</p>
                    </div>
                    <button className="btn btn-secondary" onClick={handleUnlinkExtension} disabled={isLoading}>
                      <LogOut size={16} /> Unlink Extension
                    </button>
                  </div>
                ) : (
                  <button className="btn btn-primary" onClick={handleLinkExtension} disabled={isLoading}>
                    {isLoading ? 'Linking...' : <><Shield size={16} /> Link Extension</>}
                  </button>
                )}

                <div className="extension-info">
                  <h4>How to link:</h4>
                  <ol>
                    <li>Install the Gatekeeper browser extension</li>
                    <li>Click the extension icon and open Settings</li>
                    <li>Paste the token above into the "Account Token" field</li>
                    <li>Click "Connect" — your scans will now sync automatically</li>
                  </ol>
                  <Link to="/extension" className="btn btn-ghost">
                    <Monitor size={16} /> View Extension Page
                  </Link>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'danger' && (
            <div className="account-form danger-zone">
              <h2>Danger Zone</h2>
              <p className="section-desc">Irreversible actions. Please read carefully before proceeding.</p>

              <div className="danger-item">
                <div className="danger-info">
                  <h3>Delete Account</h3>
                  <p>Permanently delete your account and all associated data including scan history, organization memberships, and settings. This cannot be undone.</p>
                </div>
                <button className="btn btn-danger" onClick={() => {
                  if (window.confirm('Type "DELETE" to confirm account deletion')) {
                    // TODO: Implement account deletion
                  }
                }}>
                  <Trash2 size={16} /> Delete Account
                </button>
              </div>

              <div className="danger-divider" />

              <div className="danger-item">
                <div className="danger-info">
                  <h3>Sign Out Everywhere</h3>
                  <p>Invalidate all active sessions and refresh tokens. You'll need to sign in again on all devices.</p>
                </div>
                <button className="btn btn-secondary" onClick={handleLogout}>
                  <LogOut size={16} /> Sign Out Everywhere
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}