import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuthStore } from '../../store/authStore';
import { useScanStore } from '../../store/scanStore';
import { useOrgStore } from '../../store/orgStore';
import { Shield, Activity, User, Monitor, Clock, TrendingUp, AlertTriangle, CheckCircle, XCircle, Loader2, ArrowRight, ExternalLink, ChevronDown, ChevronUp } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { StageCard, ReasonItem, PageInspectResult } from '../../components/ScannerComponents';

export function DashboardPage() {
  const { user } = useAuthStore();
  const { currentScan, isLoading: scanLoading, startScan, loadHistory, loadStats, clearCurrentScan } = useScanStore();
  const { loadOrgs, orgs } = useOrgStore();

  const [url, setUrl] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const [history, setHistory] = useState([]);
  const [stats, setStats] = useState(null);

  useEffect(() => {
    loadHistory({ per_page: 10 });
    loadStats();
    loadOrgs();
  }, []);

  const isValidUrl = (string) => {
    try {
      const u = new URL(string);
      return u.protocol === 'http:' || u.protocol === 'https:';
    } catch {
      return false;
    }
  };

  const handleScan = async (e) => {
    e.preventDefault();
    const trimmed = url.trim();
    if (!trimmed) return;
    if (!isValidUrl(trimmed)) {
      setUrl('');
      return;
    }
    try {
      await startScan(trimmed, true);
      setUrl('');
    } catch (err) {
      console.error('Scan failed:', err);
    }
  };

  const getVerdictClass = (verdict) => {
    if (!verdict) return '';
    const v = verdict.toLowerCase();
    if (v === 'safe') return 'safe';
    if (v === 'dangerous') return 'dangerous';
    return 'suspicious';
  };

  const getVerdictIcon = (verdict) => {
    if (!verdict) return '⏳';
    const v = verdict.toLowerCase();
    if (v === 'safe') return '✅';
    if (v === 'dangerous') return '🚨';
    return '⚠️';
  };

  const getScoreColor = (verdict) => {
    const v = (verdict || '').toLowerCase();
    if (v === 'safe') return 'var(--accent-green)';
    if (v === 'dangerous') return 'var(--accent-red)';
    return 'var(--accent-yellow)';
  };

  const ensembleRiskScore = currentScan?.risk_score || 0;
  const ensembleVerdict = currentScan?.verdict || 'Unknown';
  const inOpenPhish = currentScan?.stages?.threat_api?.in_openphish || false;
  const vClass = currentScan ? getVerdictClass(ensembleVerdict) : '';

  const lexStage = currentScan?.stages?.lexical;
  const lexStatusColor = !currentScan ? 'grey'
    : lexStage?.verdict === 'phishing' ? 'red' : 'green';
  const lexStatusLabel = !currentScan ? 'Waiting'
    : lexStage ? `${Math.round(lexStage.phishing_probability * 100)}% phish probability` : 'Error';

  const threatStage = currentScan?.stages?.threat_api;
  const threatStatusColor = !currentScan ? 'grey'
    : !threatStage?.checked ? 'grey'
    : threatStage?.in_openphish ? 'red' : 'green';
  const threatStatusLabel = !currentScan ? 'Waiting'
    : !threatStage?.checked ? 'Unavailable'
    : threatStage?.in_openphish ? 'Listed in OpenPhish feed'
    : `Not in feed (${(threatStage?.feed_size || 0).toLocaleString()} entries)`;

  const pageInspectStatus = currentScan?.pageInspect?.status || 'not_started';
  const pageStatusColor = !currentScan ? 'grey'
    : pageInspectStatus === 'pending' ? 'blue'
    : currentScan?.pageInspect?.verdict === 'phishing' ? 'red'
    : currentScan?.pageInspect?.verdict === 'suspicious' ? 'yellow'
    : currentScan?.pageInspect?.verdict === 'clean' ? 'green'
    : 'grey';
  const pageStatusLabel = !currentScan ? 'Waiting'
    : pageInspectStatus === 'pending' ? 'Analyzing page…'
    : currentScan?.pageInspect ? (currentScan.pageInspect.verdict || 'done').charAt(0).toUpperCase() + (currentScan.pageInspect.verdict || 'done').slice(1)
    : 'Done';

  return (
    <div className="dashboard-page">
      <div className="dashboard-header">
        <div>
          <h1 className="dashboard-title">Dashboard</h1>
          <p className="dashboard-subtitle">Scan URLs, view history, and monitor threats</p>
        </div>
        <div className="dashboard-actions">
          <Link to="/scans" className="btn btn-secondary">
            <Activity size={16} /> View All Scans
          </Link>
        </div>
      </div>

      <div className="stats-grid">
        <article className="stat-card">
          <div className="stat-icon"><Shield size={24} /></div>
          <div className="stat-content">
            <span className="stat-value">{stats?.total || 0}</span>
            <span className="stat-label">Total Scans</span>
          </div>
        </article>
        <article className="stat-card">
          <div className="stat-icon danger"><AlertTriangle size={24} /></div>
          <div className="stat-content">
            <span className="stat-value">{stats?.dangerous || 0}</span>
            <span className="stat-label">Dangerous</span>
          </div>
        </article>
        <article className="stat-card">
          <div className="stat-icon warning"><XCircle size={24} /></div>
          <div className="stat-content">
            <span className="stat-value">{stats?.suspicious || 0}</span>
            <span className="stat-label">Suspicious</span>
          </div>
        </article>
        <article className="stat-card">
          <div className="stat-icon success"><CheckCircle size={24} /></div>
          <div className="stat-content">
            <span className="stat-value">{stats?.safe || 0}</span>
            <span className="stat-label">Safe</span>
          </div>
        </article>
      </div>

      <div className="dashboard-grid">
        <section className="scanner-section">
          <div className="section-card">
            <header className="section-header">
              <h2><Shield size={20} /> URL Scanner</h2>
            </header>

            <form onSubmit={handleScan} className="scanner-form">
              <div className="input-card">
                <span className="input-icon">🔗</span>
                <input
                  className="url-input"
                  placeholder="Paste any URL to scan (e.g. https://suspicious-login.com/paypal)"
                  value={url}
                  onChange={e => setUrl(e.target.value)}
                  spellCheck={false}
                  autoComplete="off"
                />
                <button
                  className="scan-btn"
                  type="submit"
                  disabled={scanLoading || !url.trim()}
                >
                  {scanLoading ? (
                    <>
                      <Loader2 size={16} className="spinner" />
                      Scanning…
                    </>
                  ) : (
                    'Scan URL →'
                  )}
                </button>
              </div>
            </form>

            {currentScan && (
              <div className="scanner-results">
                <div className={`verdict-banner ${vClass}`}>
                  <div className="verdict-icon">{getVerdictIcon(ensembleVerdict)}</div>
                  <div className="verdict-info">
                    <div className="verdict-label">{ensembleVerdict}</div>
                    <div className="verdict-desc">
                      {ensembleVerdict === 'Safe'
                        ? 'No phishing indicators found. This URL appears legitimate.'
                        : ensembleVerdict === 'Dangerous'
                        ? inOpenPhish
                          ? 'This URL is listed in the OpenPhish live threat database as a confirmed phishing site.'
                          : 'Multiple high-confidence phishing indicators detected. Do NOT visit this site.'
                        : 'Suspicious structural patterns detected. Proceed with extreme caution.'}
                    </div>
                  </div>
                  <div className="verdict-score-wrap">
                    <div className="verdict-score-num" style={{ color: getScoreColor(ensembleVerdict) }}>
                      {ensembleRiskScore}<span style={{ fontSize: '1rem', opacity: 0.5 }}>/10</span>
                    </div>
                    <div className="verdict-score-label">Risk Score</div>
                    <div className="score-bar-wrap">
                      <div className="score-bar-fill" style={{ width: `${ensembleRiskScore * 10}%`, background: getScoreColor(ensembleVerdict) }} />
                    </div>
                  </div>
                </div>

                <div className="pipeline-wrapper">
                  <StageCard
                    num="1"
                    title="Lexical Analysis"
                    subtitle="URL structure inspection via trained Random Forest model"
                    status={lexStage ? 'done' : 'waiting'}
                    statusLabel={lexStatusLabel}
                    statusColor={lexStatusColor}
                    defaultOpen={true}
                  >
                    <div className="reasons-list">
                      {(currentScan.reasons || []).map((r, i) => (
                        <ReasonItem key={i} text={r} type={r.startsWith('No major') ? 'ok' : 'warn'} />
                      ))}
                    </div>
                    {lexStage && (
                      <div className="stage-latency">
                        Completed in {lexStage.latency_ms}ms · phishing probability: {Math.round(lexStage.phishing_probability * 100)}%
                      </div>
                    )}
                  </StageCard>

                  <StageCard
                    num="2"
                    title="Threat Intelligence API"
                    subtitle="Live OpenPhish feed lookup (updated every 6 hours)"
                    status={threatStage ? 'done' : 'waiting'}
                    statusLabel={threatStatusLabel}
                    statusColor={threatStatusColor}
                    defaultOpen={threatStage?.in_openphish}
                  >
                    {threatStage && (
                      <div style={{ marginTop: 12 }}>
                        <ReasonItem
                          type={threatStage.in_openphish ? 'warn' : 'ok'}
                          text={threatStage.in_openphish
                            ? '⚠ This URL is confirmed in the OpenPhish phishing database'
                            : `URL not found in the OpenPhish feed (${(threatStage.feed_size || 0).toLocaleString()} verified phishing URLs checked)`}
                        />
                        {threatStage.error && (
                          <ReasonItem type="info" text={`Feed status: ${threatStage.error}`} />
                        )}
                        <div className="stage-latency">
                          Completed in {threatStage.latency_ms}ms
                          {threatStage.cache_age_s !== undefined && ` · feed cached ${Math.round(threatStage.cache_age_s / 60)}m ago`}
                        </div>
                      </div>
                    )}
                  </StageCard>

                  <StageCard
                    num="3"
                    title="Page Content Inspection"
                    subtitle="DOM analysis, form inspection & brand impersonation detection (async)"
                    status={pageInspectStatus === 'pending' ? 'running' : 'done'}
                    statusLabel={pageStatusLabel}
                    statusColor={pageStatusColor}
                    defaultOpen={currentScan?.pageInspect?.verdict !== 'clean'}
                  >
                    {pageInspectStatus === 'pending' && !currentScan?.pageInspect && (
                      <div style={{ padding: '14px 0', fontSize: '0.82rem', color: 'var(--text-muted)' }}>
                        🔄 Page is being fetched and analyzed in the background…
                      </div>
                    )}
                    {currentScan?.pageInspect && (
                      <PageInspectResult data={currentScan.pageInspect} />
                    )}
                  </StageCard>
                </div>

                {currentScan.saved && (
                  <div className="scan-saved-notice">
                    <CheckCircle size={16} /> Scan saved to history
                  </div>
                )}
              </div>
            )}
          </div>
        </section>

        <aside className="sidebar-section">
          <div className="section-card">
            <header className="section-header">
              <h2><Activity size={20} /> Recent Scans</h2>
            </header>
            <div className="recent-scans">
              {history.length === 0 ? (
                <div className="empty-state">
                  <Shield size={32} />
                  <p>No scans yet</p>
                  <span>Scan your first URL to get started</span>
                </div>
              ) : (
                history.map(scan => (
                  <article key={scan.id} className="scan-item">
                    <div className="scan-verdict">
                      <span className={`verdict-dot ${getVerdictClass(scan.verdict)}`} />
                      <span className="scan-verdict-label">{scan.verdict}</span>
                    </div>
                    <div className="scan-info">
                      <div className="scan-url" title={scan.url}>{scan.url}</div>
                      <div className="scan-meta">
                        <span className="scan-score">{scan.risk_score}/10</span>
                        <span className="scan-time">{formatDistanceToNow(new Date(scan.created_at), { addSuffix: true })}</span>
                      </div>
                    </div>
                    <Link to={`/scans/${scan.id}`} className="scan-action">
                      <ExternalLink size={14} />
                    </Link>
                  </article>
                ))
              )}
            </div>
            {history.length > 0 && (
              <Link to="/scans" className="view-all-link">
                View all scans <ArrowRight size={14} />
              </Link>
            )}
          </div>

          {orgs.length > 0 && (
            <div className="section-card">
              <header className="section-header">
                <h2><Monitor size={20} /> Your Organizations</h2>
              </header>
              <div className="org-list">
                {orgs.slice(0, 3).map(org => (
                  <Link to={`/org-admin?org=${org.id}`} key={org.id} className="org-item">
                    <div className="org-avatar">{org.name[0]}</div>
                    <div className="org-info">
                      <span className="org-name">{org.name}</span>
                      <span className="org-role">{org.status}</span>
                    </div>
                    <ChevronRight size={16} />
                  </Link>
                ))}
              </div>
              {orgs.length > 3 && (
                <Link to="/org-admin" className="view-all-link">View all <ArrowRight size={14} /></Link>
              )}
            </div>
          )}

          <div className="section-card">
            <header className="section-header">
              <h2><TrendingUp size={20} /> Quick Actions</h2>
            </header>
            <div className="quick-actions">
              <Link to="/scans" className="quick-action">
                <Activity size={20} />
                <span>Scan History</span>
              </Link>
              <Link to="/account" className="quick-action">
                <User size={20} />
                <span>Account Settings</span>
              </Link>
              <Link to="/extension" className="quick-action">
                <Monitor size={20} />
                <span>Browser Extension</span>
              </Link>
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}