import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuthStore } from '../../store/authStore';
import { Shield, Lock, Eye, EyeOff, AlertCircle, Loader2, CheckCircle, ArrowLeft } from 'lucide-react';

export function ResetPasswordPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');
  const { resetPassword } = useAuthStore();

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [tokenValid, setTokenValid] = useState(true);

  useEffect(() => {
    if (!token) {
      setTokenValid(false);
      setError('Invalid or missing reset token');
    }
  }, [token]);

  const passwordRequirements = [
    { test: p => p.length >= 8, label: 'At least 8 characters' },
    { test: p => /[A-Z]/.test(p), label: 'One uppercase letter' },
    { test: p => /[a-z]/.test(p), label: 'One lowercase letter' },
    { test: p => /[0-9]/.test(p), label: 'One number' },
    { test: p => /[^A-Za-z0-9]/.test(p), label: 'One special character' }
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!password) {
      setError('Password is required');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    if (!passwordRequirements.every(req => req.test(password))) {
      setError('Password does not meet requirements');
      return;
    }

    setIsLoading(true);
    setError('');

    const result = await resetPassword(token, password);
    if (result.success) {
      setSubmitted(true);
    } else {
      setError(result.error || 'Password reset failed');
    }
    setIsLoading(false);
  };

  if (!tokenValid) {
    return (
      <div className="auth-page">
        <div className="auth-container">
          <div className="auth-header">
            <div className="auth-logo">
              <div className="navbar-logo-placeholder">G</div>
              <span>Gatekeeper</span>
            </div>
            <h1>Invalid Reset Link</h1>
            <p>The password reset link is invalid or has expired.</p>
          </div>
          <div className="auth-error">
            <AlertCircle size={18} />
            <span>{error}</span>
          </div>
          <Link to="/forgot-password" className="btn btn-primary btn-block">Request New Link</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="auth-page">
      <div className="auth-container">
        <div className="auth-header">
          <Link to="/login" className="back-link">
            <ArrowLeft size={18} />
            <span>Back to login</span>
          </Link>
          <div className="auth-logo">
            <div className="navbar-logo-placeholder">G</div>
            <span>Gatekeeper</span>
          </div>
          <h1>{submitted ? 'Password Reset' : 'Set New Password'}</h1>
          <p>{submitted ? 'Your password has been successfully updated.' : 'Enter your new password below.'}</p>
        </div>

        {!submitted && (
          <form onSubmit={handleSubmit} className="auth-form" noValidate>
            {error && (
              <div className="auth-error" role="alert">
                <AlertCircle size={18} />
                <span>{error}</span>
              </div>
            )}

            <div className="form-group">
              <label htmlFor="password">New Password</label>
              <div className="input-wrapper">
                <Lock size={18} className="input-icon" />
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  autoComplete="new-password"
                  disabled={isLoading}
                />
                <button
                  type="button"
                  className="toggle-password"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <div className="password-requirements">
              {passwordRequirements.map((req, i) => (
                <span key={i} className={req.test(password) ? 'met' : 'unmet'}>
                  <CheckCircle size={12} /> {req.label}
                </span>
              ))}
            </div>

            <div className="form-group">
              <label htmlFor="confirmPassword">Confirm New Password</label>
              <div className="input-wrapper">
                <Lock size={18} className="input-icon" />
                <input
                  id="confirmPassword"
                  type={showPassword ? 'text' : 'password'}
                  name="confirmPassword"
                  value={confirmPassword}
                  onChange={e => setConfirmPassword(e.target.value)}
                  placeholder="••••••••"
                  autoComplete="new-password"
                  disabled={isLoading}
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary btn-block btn-lg" disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 size={18} className="spinner" />
                  Resetting...
                </>
              ) : (
                'Reset Password'
              )}
            </button>
          </form>
        )}

        {submitted && (
          <div className="auth-success">
            <div className="success-icon"><CheckCircle size={48} /></div>
            <h2>Password Updated!</h2>
            <p>Your password has been successfully reset. You can now sign in with your new password.</p>
            <Link to="/login" className="btn btn-primary btn-block">Sign In</Link>
          </div>
        )}
      </div>
    </div>
  );
}