import { create } from 'zustand';

export const useScanStore = create((set, get) => ({
  currentScan: null,
  scanHistory: [],
  scanStats: null,
  isLoading: false,
  error: null,
  pollInterval: null,

  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),

  startScan: async (url, saveToHistory = true) => {
    set({ isLoading: true, error: null });
    try {
      const { api } = require('../services/api');
      const result = await api.scans.analyze(url);

      if (saveToHistory) {
        const saved = await api.scans.create({
          url,
          ...result
        });
        set({ currentScan: { ...result, id: saved.scan.id, saved: true } });
      } else {
        set({ currentScan: { ...result, saved: false } });
      }

      get().startPolling(url);
      return result;
    } catch (e) {
      set({ error: e.message, isLoading: false });
      throw e;
    }
  },

  startPolling: (url) => {
    const { api } = require('../services/api');
    const existing = get().pollInterval;
    if (existing) clearInterval(existing);

    const interval = setInterval(async () => {
      try {
        const data = await api.scans.pageInspect(url);
        if (data.status === 'done' && data.result) {
          set(state => ({
            currentScan: state.currentScan ? {
              ...state.currentScan,
              pageInspect: data.result,
              stages: {
                ...state.currentScan.stages,
                page_inspect: data.result
              }
            } : null
          }));
          clearInterval(interval);
          set({ pollInterval: null });
        }
      } catch (e) {
        console.error('Polling error:', e);
      }
    }, 2000);

    set({ pollInterval: interval });
  },

  stopPolling: () => {
    const interval = get().pollInterval;
    if (interval) {
      clearInterval(interval);
      set({ pollInterval: null });
    }
  },

  loadHistory: async (params = {}) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.scans.list(params);
      set({ scanHistory: data.scans, isLoading: false });
      return data;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  loadStats: async (params = {}) => {
    try {
      const { api } = require('../services/api');
      const data = await api.scans.stats(params);
      set({ scanStats: data });
      return data;
    } catch (e) {
      console.error('Stats error:', e);
    }
  },

  loadScanDetail: async (id) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.scans.get(id);
      set({ currentScan: data.scan, isLoading: false });
      return data.scan;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  deleteScan: async (id) => {
    try {
      const { api } = require('../services/api');
      await api.scans.delete(id);
      set(state => ({
        scanHistory: state.scanHistory.filter(s => s.id !== id)
      }));
    } catch (e) {
      set({ error: e.message });
    }
  },

  clearCurrentScan: () => {
    get().stopPolling();
    set({ currentScan: null });
  }
}));