import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { useAuthStore } from './store/authStore';

// Layout
import { PageLayout, PublicLayout } from './components/Layout';

// Public Pages
import { HomePage } from './pages/public/HomePage';
import { HowItWorksPage } from './pages/public/HowItWorksPage';
import { DetectionPage } from './pages/public/DetectionPage';
import { SecurityPage } from './pages/public/SecurityPage';
import { AboutPage } from './pages/public/AboutPage';
import { GetStartedPage } from './pages/public/GetStartedPage';

// Auth Pages
import { LoginPage } from './pages/auth/LoginPage';
import { RegisterPage } from './pages/auth/RegisterPage';
import { ForgotPasswordPage } from './pages/auth/ForgotPasswordPage';
import { ResetPasswordPage } from './pages/auth/ResetPasswordPage';

// Dashboard Pages
import { DashboardPage } from './pages/dashboard/DashboardPage';
import { ScanHistoryPage } from './pages/dashboard/ScanHistoryPage';
import { ScanDetailPage } from './pages/dashboard/ScanDetailPage';
import { AccountPage } from './pages/dashboard/AccountPage';
import { ExtensionPage } from './pages/dashboard/ExtensionPage';

// Org Admin
import { OrgAdminPage } from './pages/orgAdmin/OrgAdminPage';

// Super Admin
import { AdminPage } from './pages/admin/AdminPage';

import './index.css';

function ProtectedRoute({ children, allowedRoles }) {
  const { isAuthenticated, user, initializeAuth } = useAuthStore();

  useEffect(() => {
    initializeAuth();
  }, []);

  if (!isAuthenticated) {
    return <Navigate to="/login" replace state={{ from: window.location.pathname }} />;
  }

  if (allowedRoles && !allowedRoles.includes(user?.role)) {
    return <Navigate to="/dashboard" replace />;
  }

  return children;
}

function PublicOnlyRoute({ children }) {
  const { isAuthenticated, initializeAuth } = useAuthStore();

  useEffect(() => {
    initializeAuth();
  }, []);

  if (isAuthenticated) {
    return <Navigate to="/dashboard" replace />;
  }

  return children;
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        {/* Public Routes */}
        <Route element={<PublicLayout><Outlet /></PublicLayout>}>
          <Route path="/" element={<HomePage />} />
          <Route path="/how-it-works" element={<HowItWorksPage />} />
          <Route path="/detection" element={<DetectionPage />} />
          <Route path="/security" element={<SecurityPage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="/get-started" element={<GetStartedPage />} />
        </Route>

        {/* Auth Routes */}
        <Route
          path="/login"
          element={
            <PublicOnlyRoute>
              <LoginPage />
            </PublicOnlyRoute>
          }
        />
        <Route
          path="/register"
          element={
            <PublicOnlyRoute>
              <RegisterPage />
            </PublicOnlyRoute>
          }
        />
        <Route path="/forgot-password" element={<ForgotPasswordPage />} />
        <Route path="/reset-password" element={<ResetPasswordPage />} />

        {/* Protected Dashboard Routes */}
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <PageLayout title="Dashboard">
                <DashboardPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/scans"
          element={
            <ProtectedRoute>
              <PageLayout title="Scan History">
                <ScanHistoryPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/scans/:id"
          element={
            <ProtectedRoute>
              <PageLayout title="Scan Details">
                <ScanDetailPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/account"
          element={
            <ProtectedRoute>
              <PageLayout title="Account Settings">
                <AccountPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/extension"
          element={
            <ProtectedRoute>
              <PageLayout title="Browser Extension">
                <ExtensionPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />

        {/* Org Admin Routes */}
        <Route
          path="/org-admin"
          element={
            <ProtectedRoute allowedRoles={['org_admin', 'super_admin']}>
              <PageLayout title="Organization Admin">
                <OrgAdminPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />

        {/* Super Admin Routes */}
        <Route
          path="/admin"
          element={
            <ProtectedRoute allowedRoles={['super_admin']}>
              <PageLayout title="ThreatShield Admin">
                <AdminPage />
              </PageLayout>
            </ProtectedRoute>
          }
        />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
}