import { create } from 'zustand';
import { persist } from 'zustand/middleware';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:5001';

export const useAuthStore = create(
  persist(
    (set, get) => ({
      user: null,
      accessToken: null,
      refreshToken: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      setAuth: (user, accessToken, refreshToken) => {
        localStorage.setItem('access_token', accessToken);
        localStorage.setItem('refresh_token', refreshToken);
        set({ user, accessToken, refreshToken, isAuthenticated: true, error: null });
      },

      clearAuth: () => {
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
        set({ user: null, accessToken: null, refreshToken: null, isAuthenticated: false });
      },

      setLoading: (isLoading) => set({ isLoading }),
      setError: (error) => set({ error }),

      initializeAuth: async () => {
        const accessToken = localStorage.getItem('access_token');
        const refreshToken = localStorage.getItem('refresh_token');
        if (!accessToken || !refreshToken) return;

        try {
          const res = await fetch(`${API_BASE}/api/auth/me`, {
            headers: { Authorization: `Bearer ${accessToken}` }
          });
          if (res.ok) {
            const data = await res.json();
            set({ user: data.user, accessToken, refreshToken, isAuthenticated: true });
          } else {
            get().refreshAccessToken();
          }
        } catch {
          get().clearAuth();
        }
      },

      refreshAccessToken: async () => {
        const refreshToken = get().refreshToken || localStorage.getItem('refresh_token');
        if (!refreshToken) return get().clearAuth();

        try {
          const res = await fetch(`${API_BASE}/api/auth/refresh`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ refresh_token: refreshToken })
          });
          if (res.ok) {
            const data = await res.json();
            localStorage.setItem('access_token', data.access_token);
            localStorage.setItem('refresh_token', data.refresh_token);
            set({ accessToken: data.access_token, refreshToken: data.refresh_token });
          } else {
            get().clearAuth();
          }
        } catch {
          get().clearAuth();
        }
      },

      login: async (email, password) => {
        set({ isLoading: true, error: null });
        try {
          const res = await fetch(`${API_BASE}/api/auth/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email, password })
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Login failed');
          get().setAuth(data.user, data.access_token, data.refresh_token);
          return { success: true };
        } catch (e) {
          set({ error: e.message, isLoading: false });
          return { success: false, error: e.message };
        }
      },

      register: async (email, password, firstName, lastName) => {
        set({ isLoading: true, error: null });
        try {
          const res = await fetch(`${API_BASE}/api/auth/register`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email, password, first_name: firstName, last_name: lastName })
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Registration failed');
          get().setAuth(data.user, data.access_token, data.refresh_token);
          return { success: true };
        } catch (e) {
          set({ error: e.message, isLoading: false });
          return { success: false, error: e.message };
        }
      },

      logout: async () => {
        const accessToken = get().accessToken;
        if (accessToken) {
          try {
            await fetch(`${API_BASE}/api/auth/logout`, {
              method: 'POST',
              headers: { Authorization: `Bearer ${accessToken}` }
            });
          } catch {}
        }
        get().clearAuth();
      },

      updateProfile: async (updates) => {
        const accessToken = get().accessToken;
        try {
          const res = await fetch(`${API_BASE}/api/auth/me`, {
            method: 'PATCH',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${accessToken}`
            },
            body: JSON.stringify(updates)
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Update failed');
          set({ user: data.user });
          return { success: true };
        } catch (e) {
          return { success: false, error: e.message };
        }
      },

      changePassword: async (currentPassword, newPassword) => {
        const accessToken = get().accessToken;
        try {
          const res = await fetch(`${API_BASE}/api/auth/change-password`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${accessToken}`
            },
            body: JSON.stringify({ current_password: currentPassword, new_password: newPassword })
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Password change failed');
          return { success: true };
        } catch (e) {
          return { success: false, error: e.message };
        }
      },

      forgotPassword: async (email) => {
        try {
          const res = await fetch(`${API_BASE}/api/auth/forgot-password`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email })
          });
          return { success: res.ok };
        } catch {
          return { success: false };
        }
      },

      resetPassword: async (token, newPassword) => {
        try {
          const res = await fetch(`${API_BASE}/api/auth/reset-password`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token, new_password: newPassword })
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Reset failed');
          return { success: true };
        } catch (e) {
          return { success: false, error: e.message };
        }
      },

      ssoLogin: (provider) => {
        window.location.href = `${API_BASE}/api/auth/sso/${provider}`;
      },

      linkExtension: async () => {
        const accessToken = get().accessToken;
        try {
          const res = await fetch(`${API_BASE}/api/auth/extension/link`, {
            method: 'POST',
            headers: { Authorization: `Bearer ${accessToken}` }
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || 'Failed to link extension');
          return { success: true, token: data.extension_token };
        } catch (e) {
          return { success: false, error: e.message };
        }
      },

      unlinkExtension: async () => {
        const accessToken = get().accessToken;
        try {
          const res = await fetch(`${API_BASE}/api/auth/extension/unlink`, {
            method: 'POST',
            headers: { Authorization: `Bearer ${accessToken}` }
          });
          if (!res.ok) throw new Error('Failed to unlink extension');
          const user = get().user;
          if (user) set({ user: { ...user, extension_token: null, extension_linked_at: null } });
          return { success: true };
        } catch (e) {
          return { success: false, error: e.message };
        }
      },

      getExtensionStatus: async () => {
        const accessToken = get().accessToken;
        try {
          const res = await fetch(`${API_BASE}/api/auth/extension/status`, {
            headers: { Authorization: `Bearer ${accessToken}` }
          });
          return await res.json();
        } catch {
          return { linked: false };
        }
      }
    }),
    { name: 'auth-storage', partialize: (state) => ({ user: state.user, accessToken: state.accessToken, refreshToken: state.refreshToken, isAuthenticated: state.isAuthenticated }) }
  )
);