import React, { useState, useEffect } from 'react';
import { useAuthStore } from '../../store/authStore';
import { Shield, Monitor, Download, CheckCircle, AlertCircle, Copy, ExternalLink, Loader2, Globe, Github, Chrome, Edge } from 'lucide-react';

export function ExtensionPage() {
  const { user, isAuthenticated, linkExtension, unlinkExtension, getExtensionStatus, logout } = useAuthStore();

  const [extensionLinked, setExtensionLinked] = useState(false);
  const [extensionToken, setExtensionToken] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (isAuthenticated) {
      getExtensionStatus().then(data => {
        setExtensionLinked(data.linked);
        setExtensionToken(data.token || '');
      });
    }
  }, [isAuthenticated, user]);

  const handleLink = async () => {
    setIsLoading(true);
    setError('');
    setSuccess('');
    try {
      const result = await linkExtension();
      if (result.success) {
        setExtensionToken(result.token);
        setExtensionLinked(true);
        setSuccess('Extension linked successfully! Copy the token below.');
      } else {
        setError(result.error || 'Failed to link extension');
      }
    } catch (e) {
      setError('Failed to link extension');
    }
    setIsLoading(false);
  };

  const handleUnlink = async () => {
    if (!window.confirm('Unlink the browser extension?')) return;
    setIsLoading(true);
    try {
      const result = await unlinkExtension();
      if (result.success) {
        setExtensionLinked(false);
        setExtensionToken('');
        setSuccess('Extension unlinked');
      } else {
        setError('Failed to unlink extension');
      }
    } catch (e) {
      setError('Failed to unlink extension');
    }
    setIsLoading(false);
  };

  const copyToken = () => {
    navigator.clipboard.writeText(extensionToken);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const browsers = [
    { name: 'Chrome / Edge', icon: Chrome, url: 'https://chrome.google.com/webstore', color: '#4285F4' },
    { name: 'Firefox', icon: Globe, url: 'https://addons.mozilla.org', color: '#FF7139' }
  ];

  return (
    <div className="extension-page">
      <div className="page-header">
        <div>
          <h1>Browser Extension</h1>
          <p>Real-time phishing protection for every page you visit</p>
        </div>
      </div>

      <section className="extension-hero">
        <div className="hero-content">
          <div className="hero-visual">
            <div className="extension-mockup">
              <div className="mockup-header">
                <div className="mockup-dots"><span /><span /><span /></div>
                <div className="mockup-url">https://suspicious-site.com/login</div>
              </div>
              <div className="mockup-toast dangerous">
                <div className="toast-icon">🚨</div>
                <div className="toast-content">
                  <div className="toast-title">Gatekeeper — Dangerous</div>
                  <div className="toast-desc">Phishing site detected (9/10)</div>
                </div>
                <div className="toast-actions">
                  <button className="toast-btn">Full Report</button>
                  <button className="toast-btn primary">Go Back</button>
                </div>
              </div>
              <div className="mockup-page">
                <p>Page content loads here...</p>
                <p>Gatekeeper toast appears on top</p>
              </div>
            </div>
          </div>
          <div className="hero-info">
            <h2>In-Page Protection</h2>
            <p>The Gatekeeper extension analyzes every page you visit in real-time, showing instant risk toasts without leaving the site.</p>
            <ul className="hero-features">
              <li><CheckCircle size={18} /> <strong>Safe</strong> — Green toast, auto-dismisses in 5s</li>
              <li><CheckCircle size={18} /> <strong>Suspicious</strong> — Persistent yellow banner with details</li>
              <li><CheckCircle size={18} /> <strong>Dangerous</strong> — Full-screen red blocking overlay</li>
              <li><CheckCircle size={18} /> <strong>One-click reports</strong> — Full analysis in dashboard</li>
              <li><CheckCircle size={18} /> <strong>SPA compatible</strong> — Works on React, Vue, Angular apps</li>
              <li><CheckCircle size={18} /> <strong>Zero config</strong> — Install and forget</li>
            </ul>
          </div>
        </div>
      </section>

      <section className="extension-downloads">
        <div className="section-header">
          <h2>Install Extension</h2>
          <p>Available for Chromium and Firefox browsers</p>
        </div>
        <div className="download-grid">
          {browsers.map((browser, i) => (
            <a key={i} href={browser.url} target="_blank" rel="noopener" className="download-card">
              <div className="download-icon" style={{ background: browser.color }}>
                <browser.icon size={28} />
              </div>
              <h3>{browser.name}</h3>
              <p>Install from official store</p>
              <span className="download-btn">
                <Download size={16} /> Install
              </span>
            </a>
          ))}
        </div>
        <div className="github-link">
          <a href="https://github.com/ashh-beep/Gatekeeper/tree/main/extension" target="_blank" rel="noopener">
            <Github size={18} /> View Source on GitHub
          </a>
        </div>
      </section>

      <section className="extension-linking">
        <div className="section-header">
          <h2>Link to Your Account</h2>
          <p>Sync scan history, access personalized settings, and manage extension from dashboard</p>
        </div>

        <div className="linking-card">
          {isAuthenticated ? (
            <>
              <div className="linking-status">
                <div className={`status-badge ${extensionLinked ? 'connected' : 'disconnected'}`}>
                  <span className="status-dot" />
                  {extensionLinked ? 'Connected' : 'Not Connected'}
                </div>
              </div>

              {extensionLinked ? (
                <div className="token-section">
                  <h3>Your Extension Token</h3>
                  <p>Copy this token and paste it in the extension settings (click extension icon → Settings → Account Token)</p>
                  <div className="token-display">
                    <code>{extensionToken}</code>
                    <button className="btn btn-secondary" onClick={copyToken}>
                      {copied ? (
                        <> <CheckCircle size={16} /> Copied! </>
                      ) : (
                        <> <Copy size={16} /> Copy </>
                      )}
                    </button>
                  </div>
                  <button className="btn btn-secondary danger" onClick={handleUnlink} disabled={isLoading}>
                    <AlertCircle size={16} /> Unlink Extension
                  </button>
                </div>
              ) : (
                <div className="link-action">
                  <p>Link the extension to sync your scan history and access personalized protection.</p>
                  <button className="btn btn-primary" onClick={handleLink} disabled={isLoading}>
                    {isLoading ? (<Loader2 size={16} className="spinner" />) : (<><Shield size={16} /> Link Extension</>)}
                  </button>
                </div>
              )}

              <div className="extension-features">
                <h4>When linked, you get:</h4>
                <ul>
                  <li><CheckCircle size={16} /> Scan history synced to dashboard</li>
                  <li><CheckCircle size={16} /> Organization-level policies</li>
                  <li><CheckCircle size={16} /> Custom block/allow lists</li>
                  <li><CheckCircle size={16} /> Admin visibility into team scans</li>
                </ul>
              </div>
            </>
          ) : (
            <div className="auth-prompt">
              <Shield size={48} />
              <h3>Sign in to link extension</h3>
              <p>Create an account or sign in to connect the browser extension and sync your scans.</p>
              <div className="auth-buttons">
                <a href="/login" className="btn btn-secondary">Sign In</a>
                <a href="/register" className="btn btn-primary">Create Account</a>
              </div>
            </div>
          )}
        </div>
      </section>

      <section className="extension-how-it-works">
        <div className="section-header">
          <h2>How It Works</h2>
        </div>
        <div className="how-grid">
          <article className="how-card">
            <div className="how-icon"><Monitor size={24} /></div>
            <h3>Automatic Scanning</h3>
            <p>Every navigation triggers a background scan via the Gatekeeper API — no clicks needed.</p>
          </article>
          <article className="how-card">
            <div className="how-icon"><Zap size={24} /></div>
            <h3>Three-Layer Analysis</h3>
            <p>Same lexical, threat intelligence, and page inspection pipeline as the dashboard.</p>
          </article>
          <article className="how-card">
            <div className="how-icon"><AlertCircle size={24} /></div>
            <h3>Contextual Alerts</h3>
            <p>Risk-appropriate UI: subtle toast for safe, persistent banner for suspicious, blocking overlay for dangerous.</p>
          </article>
          <article className="how-card">
            <div className="how-icon"><ExternalLink size={24} /></div>
            <h3>One-Click Reports</h3>
            <p>Click any alert to open the full analysis in your dashboard with all three stages detailed.</p>
          </article>
        </div>
      </section>
    </div>
  );
}