import React, { useEffect, useState } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { useScanStore } from '../../store/scanStore';
import { useAuthStore } from '../../store/authStore';
import { formatDistanceToNow } from 'date-fns';
import { Shield, AlertTriangle, CheckCircle, Loader2, ArrowLeft, ExternalLink, Share2, Trash2, Clock, Zap, Search, Eye, Download } from 'lucide-react';
import { StageCard, ReasonItem, PageInspectResult } from '../../components/ScannerComponents';

export function ScanDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { currentScan, isLoading, loadScanDetail, deleteScan } = useScanStore();
  const { user } = useAuthStore();

  const [scan, setScan] = useState(null);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    loadScanDetail(id).then(data => setScan(data));
  }, [id]);

  const getVerdictClass = (verdict) => {
    if (!verdict) return '';
    const v = verdict.toLowerCase();
    if (v === 'safe') return 'safe';
    if (v === 'dangerous') return 'dangerous';
    return 'suspicious';
  };

  const getVerdictIcon = (verdict) => {
    if (!verdict) return '⏳';
    const v = verdict.toLowerCase();
    if (v === 'safe') return '✅';
    if (v === 'dangerous') return '🚨';
    return '⚠️';
  };

  const getScoreColor = (verdict) => {
    const v = (verdict || '').toLowerCase();
    if (v === 'safe') return 'var(--accent-green)';
    if (v === 'dangerous') return 'var(--accent-red)';
    return 'var(--accent-yellow)';
  };

  const handleDelete = async () => {
    if (!window.confirm('Are you sure you want to delete this scan from history?')) return;
    setDeleting(true);
    try {
      await deleteScan(id);
      navigate('/scans');
    } catch (e) {
      console.error('Delete failed:', e);
    } finally {
      setDeleting(false);
    }
  };

  const handleShare = () => {
    const url = window.location.href;
    if (navigator.share) {
      navigator.share({ title: `Gatekeeper Scan: ${scan?.url}`, url });
    } else {
      navigator.clipboard.writeText(url);
    }
  };

  const downloadReport = () => {
    const report = {
      url: scan?.url,
      verdict: scan?.verdict,
      risk_score: scan?.risk_score,
      risk_color: scan?.risk_color,
      phishing_probability: scan?.phishing_probability,
      prediction: scan?.prediction,
      reasons: scan?.reasons,
      stages: scan?.stages,
      page_inspect_result: scan?.pageInspectResult,
      scanned_at: scan?.created_at
    };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gatekeeper-scan-${scan?.id}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (isLoading && !scan) {
    return (
      <div className="scan-detail-page loading">
        <div className="loading-state">
          <Loader2 size={32} className="spinner" />
          <p>Loading scan details...</p>
        </div>
      </div>
    );
  }

  if (!scan) {
    return (
      <div className="scan-detail-page">
        <div className="error-state">
          <AlertTriangle size={48} />
          <h3>Scan not found</h3>
          <Link to="/scans" className="btn btn-primary">Back to History</Link>
        </div>
      </div>
    );
  }

  const ensembleRiskScore = scan.risk_score || 0;
  const ensembleVerdict = scan.verdict || 'Unknown';
  const inOpenPhish = scan.stages?.threat_api?.in_openphish || false;
  const vClass = getVerdictClass(ensembleVerdict);

  const lexStage = scan.stages?.lexical;
  const lexStatusColor = !scan ? 'grey' : lexStage?.verdict === 'phishing' ? 'red' : 'green';
  const lexStatusLabel = !scan ? 'Waiting' : lexStage ? `${Math.round(lexStage.phishing_probability * 100)}% phish probability` : 'Error';

  const threatStage = scan.stages?.threat_api;
  const threatStatusColor = !scan ? 'grey' : !threatStage?.checked ? 'grey' : threatStage?.in_openphish ? 'red' : 'green';
  const threatStatusLabel = !scan ? 'Waiting' : !threatStage?.checked ? 'Unavailable' : threatStage?.in_openphish ? 'Listed in OpenPhish feed' : `Not in feed (${(threatStage?.feed_size || 0).toLocaleString()} entries)`;

  const pageInspectResult = scan.pageInspectResult || scan.stages?.page_inspect;
  const pageInspectStatus = pageInspectResult?.status || 'not_started';
  const pageStatusColor = !scan ? 'grey' : pageInspectStatus === 'pending' ? 'blue' : pageInspectResult?.verdict === 'phishing' ? 'red' : pageInspectResult?.verdict === 'suspicious' ? 'yellow' : pageInspectResult?.verdict === 'clean' ? 'green' : 'grey';
  const pageStatusLabel = !scan ? 'Waiting' : pageInspectStatus === 'pending' ? 'Analyzing page…' : pageInspectResult?.verdict ? pageInspectResult.verdict.charAt(0).toUpperCase() + pageInspectResult.verdict.slice(1) : 'Done';

  return (
    <div className="scan-detail-page">
      <div className="detail-header">
        <Link to="/scans" className="back-link">
          <ArrowLeft size={18} />
          <span>Back to History</span>
        </Link>
        <div className="detail-actions">
          <button className="btn btn-secondary" onClick={downloadReport}>
            <Download size={16} /> Export JSON
          </button>
          <button className="btn btn-secondary" onClick={handleShare}>
            <Share2 size={16} /> Share
          </button>
          <button className="btn btn-secondary danger" onClick={handleDelete} disabled={deleting}>
            <Trash2 size={16} /> Delete
          </button>
        </div>
      </div>

      <div className="scan-detail-card">
        <div className="scan-meta-header">
          <div className="scan-url-section">
            <div className="scan-url-row">
              <span className="scan-url">{scan.url}</span>
              <span className={`verdict-badge-large ${vClass}`}>
                {getVerdictIcon(ensembleVerdict)} {ensembleVerdict}
              </span>
            </div>
            <div className="scan-meta-grid">
              <div className="meta-item">
                <span className="meta-label">Risk Score</span>
                <span className="meta-value" style={{ color: getScoreColor(ensembleVerdict) }}>{ensembleRiskScore}/10</span>
              </div>
              <div className="meta-item">
                <span className="meta-label">Phishing Probability</span>
                <span className="meta-value">{(scan.phishing_probability * 100).toFixed(1)}%</span>
              </div>
              <div className="meta-item">
                <span className="meta-label">ML Prediction</span>
                <span className="meta-value">{scan.prediction === 1 ? 'Phishing' : 'Safe'}</span>
              </div>
              <div className="meta-item">
                <span className="meta-label">OpenPhish</span>
                <span className="meta-value">{inOpenPhish ? '⚠ Listed' : '✓ Not listed'}</span>
              </div>
              <div className="meta-item">
                <span className="meta-label">Scanned</span>
                <span className="meta-value">{formatDistanceToNow(new Date(scan.created_at), { addSuffix: true })}</span>
              </div>
              <div className="meta-item">
                <span className="meta-label">Scan ID</span>
                <span className="meta-value mono">{scan.id}</span>
              </div>
            </div>
          </div>

          <div className="verdict-banner-detail {vClass}">
            <div className="verdict-icon-large">{getVerdictIcon(ensembleVerdict)}</div>
            <div className="verdict-info-detail">
              <div className="verdict-label-detail">{ensembleVerdict}</div>
              <div className="verdict-desc-detail">
                {ensembleVerdict === 'Safe'
                  ? 'No phishing indicators found. This URL appears legitimate based on structural analysis and threat intelligence.'
                  : ensembleVerdict === 'Dangerous'
                  ? inOpenPhish
                    ? 'This URL is listed in the OpenPhish live threat database as a confirmed phishing site.'
                    : 'Multiple high-confidence phishing indicators detected. Do NOT visit this site.'
                  : 'Suspicious structural patterns detected. Proceed with extreme caution and do not enter any credentials.'}
              </div>
            </div>
            <div className="verdict-score-detail" style={{ borderLeftColor: getScoreColor(ensembleVerdict) }}>
              <div className="score-number" style={{ color: getScoreColor(ensembleVerdict) }}>{ensembleRiskScore}</div>
              <div className="score-label">/10 Risk</div>
            </div>
          </div>
        </div>

        <div className="detail-sections">
          <div className="pipeline-wrapper">
            <StageCard
              num="1"
              title="Lexical Analysis"
              subtitle="URL structure inspection via trained Random Forest model"
              status={lexStage ? 'done' : 'waiting'}
              statusLabel={lexStatusLabel}
              statusColor={lexStatusColor}
              defaultOpen={true}
            >
              <div className="reasons-list">
                {(scan.reasons || []).map((r, i) => (
                  <ReasonItem key={i} text={r} type={r.startsWith('No major') ? 'ok' : 'warn'} />
                ))}
              </div>
              {lexStage && (
                <div className="stage-latency">
                  Completed in {lexStage.latency_ms}ms · phishing probability: {Math.round(lexStage.phishing_probability * 100)}%
                </div>
              )}
            </StageCard>

            <StageCard
              num="2"
              title="Threat Intelligence API"
              subtitle="Live OpenPhish feed lookup (updated every 6 hours)"
              status={threatStage ? 'done' : 'waiting'}
              statusLabel={threatStatusLabel}
              statusColor={threatStatusColor}
              defaultOpen={threatStage?.in_openphish}
            >
              {threatStage && (
                <div style={{ marginTop: 12 }}>
                  <ReasonItem
                    type={threatStage.in_openphish ? 'warn' : 'ok'}
                    text={threatStage.in_openphish
                      ? '⚠ This URL is confirmed in the OpenPhish phishing database'
                      : `URL not found in the OpenPhish feed (${(threatStage.feed_size || 0).toLocaleString()} verified phishing URLs checked)`}
                  />
                  {threatStage.error && (
                    <ReasonItem type="info" text={`Feed status: ${threatStage.error}`} />
                  )}
                  <div className="stage-latency">
                    Completed in {threatStage.latency_ms}ms
                    {threatStage.cache_age_s !== undefined && ` · feed cached ${Math.round(threatStage.cache_age_s / 60)}m ago`}
                  </div>
                </div>
              )}
            </StageCard>

            <StageCard
              num="3"
              title="Page Content Inspection"
              subtitle="DOM analysis, form inspection & brand impersonation detection (async)"
              status={pageInspectStatus === 'pending' ? 'running' : 'done'}
              statusLabel={pageStatusLabel}
              statusColor={pageStatusColor}
              defaultOpen={pageInspectResult?.verdict !== 'clean'}
            >
              {pageInspectStatus === 'pending' && !pageInspectResult && (
                <div style={{ padding: '14px 0', fontSize: '0.82rem', color: 'var(--text-muted)' }}>
                  🔄 Page is being fetched and analyzed in the background…
                </div>
              )}
              {pageInspectResult && (
                <PageInspectResult data={pageInspectResult} />
              )}
            </StageCard>
          </div>
        </div>
      </div>
    </div>
  );
}