import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAdminStore } from '../../store/adminStore';
import { Shield, Users, Building2, Activity, TrendingUp, Plus, Search, Filter, ChevronDown, Loader2, Edit, Trash2, Eye, MoreVertical, CheckCircle, AlertTriangle, XCircle, UserCheck, UserX, Settings, Download } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';

export function AdminPage() {
  const navigate = useNavigate();
  const { dashboard, allUsers, allOrgs, allActivity, globalStats, isLoading, loadDashboard, loadUsers, loadOrgs, loadActivity, loadStats, createUser, updateUser, deleteUser, createOrg, updateOrg, deleteOrg } = useAdminStore();

  const [activeTab, setActiveTab] = useState('dashboard');
  const [showCreateUser, setShowCreateUser] = useState(false);
  const [showCreateOrg, setShowCreateOrg] = useState(false);
  const [userSearch, setUserSearch] = useState('');
  const [userRoleFilter, setUserRoleFilter] = useState('');
  const [userPage, setUserPage] = useState(1);
  const [orgSearch, setOrgSearch] = useState('');
  const [orgStatusFilter, setOrgStatusFilter] = useState('');
  const [orgPage, setOrgPage] = useState(1);
  const [activityPage, setActivityPage] = useState(1);
  const [activityFilter, setActivityFilter] = useState('');
  const [newUser, setNewUser] = useState({ email: '', password: '', first_name: '', last_name: '', role: 'user', organization_id: '' });
  const [newOrg, setNewOrg] = useState({ name: '', slug: '', domain: '', admin_id: '' });
  const [createLoading, setCreateLoading] = useState(false);
  const [createError, setCreateError] = useState('');

  useEffect(() => {
    loadDashboard();
    loadStats();
  }, []);

  useEffect(() => {
    loadUsers({ page: userPage, per_page: 20, search: userSearch, role: userRoleFilter });
  }, [userPage, userSearch, userRoleFilter]);

  useEffect(() => {
    loadOrgs({ page: orgPage, per_page: 20, search: orgSearch, status: orgStatusFilter });
  }, [orgPage, orgSearch, orgStatusFilter]);

  useEffect(() => {
    loadActivity({ page: activityPage, per_page: 50, type: activityFilter });
  }, [activityPage, activityFilter]);

  const handleCreateUser = async (e) => {
    e.preventDefault();
    setCreateLoading(true);
    setCreateError('');
    try {
      await createUser(newUser);
      setShowCreateUser(false);
      setNewUser({ email: '', password: '', first_name: '', last_name: '', role: 'user', organization_id: '' });
    } catch (e) {
      setCreateError(e.message || 'Failed to create user');
    }
    setCreateLoading(false);
  };

  const handleCreateOrg = async (e) => {
    e.preventDefault();
    setCreateLoading(true);
    setCreateError('');
    try {
      await createOrg(newOrg);
      setShowCreateOrg(false);
      setNewOrg({ name: '', slug: '', domain: '', admin_id: '' });
    } catch (e) {
      setCreateError(e.message || 'Failed to create organization');
    }
    setCreateLoading(false);
  };

  const handleUserRoleChange = async (id, role) => {
    try {
      await updateUser(id, { role });
    } catch (e) {
      alert('Failed to update user: ' + e.message);
    }
  };

  const handleUserStatusChange = async (id, is_active) => {
    try {
      await updateUser(id, { is_active });
    } catch (e) {
      alert('Failed to update user: ' + e.message);
    }
  };

  const handleDeleteUser = async (id) => {
    if (!window.confirm('Delete this user and all their data?')) return;
    try {
      await deleteUser(id);
    } catch (e) {
      alert('Failed to delete user: ' + e.message);
    }
  };

  const handleOrgStatusChange = async (id, status) => {
    try {
      await updateOrg(id, { status });
    } catch (e) {
      alert('Failed to update org: ' + e.message);
    }
  };

  const handleDeleteOrg = async (id) => {
    if (!window.confirm('Delete this organization and all its data?')) return;
    try {
      await deleteOrg(id);
    } catch (e) {
      alert('Failed to delete org: ' + e.message);
    }
  };

  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: TrendingUp },
    { id: 'users', label: 'Users', icon: Users },
    { id: 'organizations', label: 'Organizations', icon: Building2 },
    { id: 'activity', label: 'Activity', icon: Activity }
  ];

  return (
    <div className="admin-page">
      <div className="page-header">
        <div>
          <h1>ThreatShield Admin</h1>
          <p>Super administrator panel for platform management</p>
        </div>
      </div>

      <div className="admin-layout">
        <nav className="admin-nav">
          {tabs.map(tab => (
            <button
              key={tab.id}
              className={`admin-nav-item ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              <tab.icon size={18} />
              <span>{tab.label}</span>
            </button>
          ))}
        </nav>

        <div className="admin-content">
          {activeTab === 'dashboard' && (
            <div className="dashboard-tab">
              {dashboard && (
                <>
                  <div className="stats-grid">
                    <article className="stat-card">
                      <div className="stat-icon"><Users size={24} /></div>
                      <div className="stat-content">
                        <span className="stat-value">{dashboard.users?.total || 0}</span>
                        <span className="stat-label">Total Users</span>
                      </div>
                    </article>
                    <article className="stat-card">
                      <div className="stat-icon"><UserCheck size={24} /></div>
                      <div className="stat-content">
                        <span className="stat-value">{dashboard.users?.active || 0}</span>
                        <span className="stat-label">Active Users</span>
                      </div>
                    </article>
                    <article className="stat-card">
                      <div className="stat-icon"><Building2 size={24} /></div>
                      <div className="stat-content">
                        <span className="stat-value">{dashboard.organizations?.total || 0}</span>
                        <span className="stat-label">Total Orgs</span>
                      </div>
                    </article>
                    <article className="stat-card">
                      <div className="stat-icon"><Building2 size={24} /></div>
                      <div className="stat-content">
                        <span className="stat-value">{dashboard.organizations?.active || 0}</span>
                        <span className="stat-label">Active Orgs</span>
                      </div>
                    </article>
                    <article className="stat-card">
                      <div className="stat-icon"><Shield size={24} /></div>
                      <div className="stat-content">
                        <span className="stat-value">{dashboard.scans?.total || 0}</span>
                        <span className="stat-label">Total Scans</span>
                      </div>
                    </article>
                  </div>

                  <div className="dashboard-charts">
                    <section className="chart-card">
                      <h3>Scans by Verdict</h3>
                      <div className="chart-bars">
                        {Object.entries(dashboard.scans?.by_verdict || {}).map(([verdict, count]) => (
                          <div key={verdict} className="chart-bar">
                            <span className="chart-label">{verdict}</span>
                            <div className="chart-bar-track">
                              <div className="chart-bar-fill" style={{ width: `${dashboard.scans.total ? (count / dashboard.scans.total * 100) : 0}%` }} />
                            </div>
                            <span className="chart-value">{count}</span>
                          </div>
                        ))}
                      </div>
                    </section>

                    <section className="chart-card">
                      <h3>Orgs by Status</h3>
                      <div className="chart-bars">
                        {Object.entries(dashboard.organizations_by_status || {}).map(([status, count]) => (
                          <div key={status} className="chart-bar">
                            <span className="chart-label">{status}</span>
                            <div className="chart-bar-track">
                              <div className="chart-bar-fill" style={{ width: `${dashboard.organizations.total ? (count / dashboard.organizations.total * 100) : 0}%` }} />
                            </div>
                            <span className="chart-value">{count}</span>
                          </div>
                        ))}
                      </div>
                    </section>
                  </div>

                  <div className="recent-sections">
                    <section className="section-card">
                      <header className="section-header">
                        <h3><Users size={20} /> Recent Users</h3>
                      </header>
                      <div className="recent-table">
                        {dashboard.recent_users?.map(u => (
                          <div key={u.id} className="recent-row">
                            <div className="user-info">
                              <div className="user-avatar">{u.first_name?.[0]}{u.last_name?.[0]}</div>
                              <div>
                                <span>{u.first_name} {u.last_name}</span>
                                <span className="user-email">{u.email}</span>
                              </div>
                            </div>
                            <span className={`role-badge ${u.role}`}>{u.role}</span>
                            <span className="recent-time">{formatDistanceToNow(new Date(u.created_at), { addSuffix: true })}</span>
                          </div>
                        ))}
                      </div>
                    </section>

                    <section className="section-card">
                      <header className="section-header">
                        <h3><Building2 size={20} /> Recent Organizations</h3>
                      </header>
                      <div className="recent-table">
                        {dashboard.recent_organizations?.map(o => (
                          <div key={o.id} className="recent-row">
                            <div className="org-info">
                              <div className="org-avatar">{o.name[0]}</div>
                              <div>
                                <span>{o.name}</span>
                                <span className="org-slug">/{o.slug}</span>
                              </div>
                            </div>
                            <span className={`org-status ${o.status}`}>{o.status}</span>
                            <span className="recent-time">{formatDistanceToNow(new Date(o.created_at), { addSuffix: true })}</span>
                          </div>
                        ))}
                      </div>
                    </section>
                  </div>
                </>
              )}
            </div>
          )}

          {activeTab === 'users' && (
            <div className="users-tab">
              <div className="tab-header">
                <h2>All Users</h2>
                <button className="btn btn-primary" onClick={() => setShowCreateUser(true)}>
                  <Plus size={16} /> Create User
                </button>
              </div>

              <div className="filters-bar">
                <div className="search-box">
                  <Search size={18} />
                  <input
                    type="text"
                    placeholder="Search users..."
                    value={userSearch}
                    onChange={e => { setUserSearch(e.target.value); setUserPage(1); }}
                  />
                </div>
                <div className="filter-group">
                  <select value={userRoleFilter} onChange={e => { setUserRoleFilter(e.target.value); setUserPage(1); }} className="filter-select">
                    <option value="">All Roles</option>
                    <option value="user">User</option>
                    <option value="org_admin">Org Admin</option>
                    <option value="super_admin">Super Admin</option>
                  </select>
                </div>
              </div>

              {isLoading && allUsers.length === 0 ? (
                <div className="loading-state"><Loader2 size={32} className="spinner" /></div>
              ) : (
                <>
                  <div className="table-container">
                    <table className="admin-table">
                      <thead>
                        <tr>
                          <th>User</th>
                          <th>Email</th>
                          <th>Role</th>
                          <th>Status</th>
                          <th>Joined</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {allUsers.map(u => (
                          <tr key={u.id}>
                            <td>
                              <div className="user-info">
                                <div className="user-avatar">{u.first_name?.[0]}{u.last_name?.[0]}</div>
                                <span>{u.first_name} {u.last_name}</span>
                              </div>
                            </td>
                            <td>{u.email}</td>
                            <td>
                              <select
                                value={u.role}
                                onChange={e => handleUserRoleChange(u.id, e.target.value)}
                                className="role-select"
                              >
                                <option value="user">User</option>
                                <option value="org_admin">Org Admin</option>
                                <option value="super_admin">Super Admin</option>
                              </select>
                            </td>
                            <td>
                              <label className="toggle">
                                <input
                                  type="checkbox"
                                  checked={u.is_active}
                                  onChange={e => handleUserStatusChange(u.id, e.target.checked)}
                                />
                                <span className="toggle-slider" />
                              </label>
                            </td>
                            <td>{formatDistanceToNow(new Date(u.created_at), { addSuffix: true })}</td>
                            <td>
                              <button className="btn-icon danger" onClick={() => handleDeleteUser(u.id)} title="Delete">
                                <Trash2 size={16} />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="pagination">
                    <button className="btn btn-secondary" disabled={userPage === 1} onClick={() => setUserPage(p => p - 1)}>Previous</button>
                    <span>Page {userPage}</span>
                    <button className="btn btn-secondary" onClick={() => setUserPage(p => p + 1)}>Next</button>
                  </div>
                </>
              )}
            </div>
          )}

          {activeTab === 'organizations' && (
            <div className="orgs-tab">
              <div className="tab-header">
                <h2>All Organizations</h2>
                <button className="btn btn-primary" onClick={() => setShowCreateOrg(true)}>
                  <Plus size={16} /> Create Organization
                </button>
              </div>

              <div className="filters-bar">
                <div className="search-box">
                  <Search size={18} />
                  <input
                    type="text"
                    placeholder="Search organizations..."
                    value={orgSearch}
                    onChange={e => { setOrgSearch(e.target.value); setOrgPage(1); }}
                  />
                </div>
                <div className="filter-group">
                  <select value={orgStatusFilter} onChange={e => { setOrgStatusFilter(e.target.value); setOrgPage(1); }} className="filter-select">
                    <option value="">All Statuses</option>
                    <option value="active">Active</option>
                    <option value="inactive">Inactive</option>
                    <option value="suspended">Suspended</option>
                  </select>
                </div>
              </div>

              {isLoading && allOrgs.length === 0 ? (
                <div className="loading-state"><Loader2 size={32} className="spinner" /></div>
              ) : (
                <>
                  <div className="table-container">
                    <table className="admin-table">
                      <thead>
                        <tr>
                          <th>Organization</th>
                          <th>Slug</th>
                          <th>Domain</th>
                          <th>Status</th>
                          <th>Members</th>
                          <th>Created</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {allOrgs.map(o => (
                          <tr key={o.id}>
                            <td>
                              <div className="org-info">
                                <div className="org-avatar">{o.name[0]}</div>
                                <span>{o.name}</span>
                              </div>
                            </td>
                            <td>/{o.slug}</td>
                            <td>{o.domain || '—'}</td>
                            <td>
                              <select
                                value={o.status}
                                onChange={e => handleOrgStatusChange(o.id, e.target.value)}
                                className="status-select"
                              >
                                <option value="active">Active</option>
                                <option value="inactive">Inactive</option>
                                <option value="suspended">Suspended</option>
                              </select>
                            </td>
                            <td>{o.memberships?.length || 0}</td>
                            <td>{formatDistanceToNow(new Date(o.created_at), { addSuffix: true })}</td>
                            <td>
                              <button className="btn-icon danger" onClick={() => handleDeleteOrg(o.id)} title="Delete">
                                <Trash2 size={16} />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="pagination">
                    <button className="btn btn-secondary" disabled={orgPage === 1} onClick={() => setOrgPage(p => p - 1)}>Previous</button>
                    <span>Page {orgPage}</span>
                    <button className="btn btn-secondary" onClick={() => setOrgPage(p => p + 1)}>Next</button>
                  </div>
                </>
              )}
            </div>
          )}

          {activeTab === 'activity' && (
            <div className="activity-tab">
              <h2>Global Activity Log</h2>
              <div className="filters-bar">
                <div className="filter-group">
                  <select value={activityFilter} onChange={e => { setActivityFilter(e.target.value); setActivityPage(1); }} className="filter-select">
                    <option value="">All Types</option>
                    <option value="user_login">User Login</option>
                    <option value="user_register">User Register</option>
                    <option value="scan_created">Scan Created</option>
                    <option value="org_created">Org Created</option>
                    <option value="org_member_added">Member Added</option>
                    <option value="admin_user_created">Admin User Created</option>
                    <option value="admin_org_created">Admin Org Created</option>
                  </select>
                </div>
              </div>

              <div className="table-container">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>Time</th>
                      <th>User</th>
                      <th>Organization</th>
                      <th>Type</th>
                      <th>Description</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allActivity.map(a => (
                      <tr key={a.id}>
                        <td>{formatDistanceToNow(new Date(a.created_at), { addSuffix: true })}</td>
                        <td>{a.user ? `${a.user.first_name} ${a.user.last_name}` : 'System'}</td>
                        <td>{a.organization?.name || '—'}</td>
                        <td><span className="activity-type">{a.type.replace(/_/g, ' ')}</span></td>
                        <td>{a.description}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="pagination">
                <button className="btn btn-secondary" disabled={activityPage === 1} onClick={() => setActivityPage(p => p - 1)}>Previous</button>
                <span>Page {activityPage}</span>
                <button className="btn btn-secondary" onClick={() => setActivityPage(p => p + 1)}>Next</button>
              </div>
            </div>
          )}
        </div>
      </div>

      {showCreateUser && (
        <div className="modal-overlay" onClick={() => setShowCreateUser(false)}>
          <div className="modal large" onClick={e => e.stopPropagation()}>
            <h3>Create User</h3>
            <form onSubmit={handleCreateUser}>
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="first_name">First Name</label>
                  <input id="first_name" value={newUser.first_name} onChange={e => setNewUser({...newUser, first_name: e.target.value})} required />
                </div>
                <div className="form-group">
                  <label htmlFor="last_name">Last Name</label>
                  <input id="last_name" value={newUser.last_name} onChange={e => setNewUser({...newUser, last_name: e.target.value})} required />
                </div>
              </div>
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input id="email" type="email" value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} required />
              </div>
              <div className="form-group">
                <label htmlFor="password">Password</label>
                <input id="password" type="password" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} required minLength={8} />
              </div>
              <div className="form-group">
                <label htmlFor="role">Role</label>
                <select id="role" value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value})}>
                  <option value="user">User</option>
                  <option value="org_admin">Org Admin</option>
                  <option value="super_admin">Super Admin</option>
                </select>
              </div>
              <div className="form-group">
                <label htmlFor="organization_id">Organization (optional)</label>
                <select id="organization_id" value={newUser.organization_id} onChange={e => setNewUser({...newUser, organization_id: e.target.value})}>
                  <option value="">None</option>
                  {allOrgs.filter(o => o.status === 'active').map(o => (
                    <option key={o.id} value={o.id}>{o.name}</option>
                  ))}
                </select>
              </div>
              {createError && <div className="alert error">{createError}</div>}
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowCreateUser(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={createLoading}>
                  {createLoading ? 'Creating...' : 'Create User'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showCreateOrg && (
        <div className="modal-overlay" onClick={() => setShowCreateOrg(false)}>
          <div className="modal large" onClick={e => e.stopPropagation()}>
            <h3>Create Organization</h3>
            <form onSubmit={handleCreateOrg}>
              <div className="form-group">
                <label htmlFor="name">Name</label>
                <input id="name" value={newOrg.name} onChange={e => setNewOrg({...newOrg, name: e.target.value})} required />
              </div>
              <div className="form-group">
                <label htmlFor="slug">Slug</label>
                <input id="slug" value={newOrg.slug} onChange={e => setNewOrg({...newOrg, slug: e.target.value.toLowerCase()})} required />
              </div>
              <div className="form-group">
                <label htmlFor="domain">Domain (optional)</label>
                <input id="domain" value={newOrg.domain} onChange={e => setNewOrg({...newOrg, domain: e.target.value})} placeholder="company.com" />
              </div>
              <div className="form-group">
                <label htmlFor="admin_id">Initial Admin (optional)</label>
                <select id="admin_id" value={newOrg.admin_id} onChange={e => setNewOrg({...newOrg, admin_id: e.target.value})}>
                  <option value="">None</option>
                  {allUsers.filter(u => u.role === 'user' || u.role === 'org_admin').map(u => (
                    <option key={u.id} value={u.id}>{u.first_name} {u.last_name} ({u.email})</option>
                  ))}
                </select>
              </div>
              {createError && <div className="alert error">{createError}</div>}
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowCreateOrg(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={createLoading}>
                  {createLoading ? 'Creating...' : 'Create Organization'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}