import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useScanStore } from '../../store/scanStore';
import { formatDistanceToNow } from 'date-fns';
import { Shield, AlertTriangle, CheckCircle, Search, Filter, ChevronDown, Loader2, Trash2, ExternalLink } from 'lucide-react';

export function ScanHistoryPage() {
  const { scanHistory, isLoading, loadHistory, deleteScan, scanStats } = useScanStore();
  const [page, setPage] = useState(1);
  const [verdictFilter, setVerdictFilter] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [stats, setStats] = useState(null);
  const perPage = 20;

  useEffect(() => {
    loadHistory({ page, per_page: perPage, verdict: verdictFilter || undefined });
  }, [page, verdictFilter]);

  useEffect(() => {
    const fetchStats = async () => {
      const data = await useScanStore.getState().loadStats({ verdict: verdictFilter || undefined });
      setStats(data);
    };
    fetchStats();
  }, [verdictFilter]);

  const getVerdictClass = (verdict) => {
    const v = verdict.toLowerCase();
    if (v === 'safe') return 'safe';
    if (v === 'dangerous') return 'dangerous';
    return 'suspicious';
  };

  const getVerdictIcon = (verdict) => {
    const v = verdict.toLowerCase();
    if (v === 'safe') return <CheckCircle size={16} />;
    if (v === 'dangerous') return <AlertTriangle size={16} />;
    return <Shield size={16} />;
  };

  const handleDelete = async (id) => {
    if (window.confirm('Delete this scan from history?')) {
      await deleteScan(id);
    }
  };

  return (
    <div className="scan-history-page">
      <div className="page-header-with-actions">
        <div>
          <h1>Scan History</h1>
          <p>View and manage all your URL scans</p>
        </div>
      </div>

      <div className="stats-bar">
        <div className="stat-pill total">
          <Shield size={16} />
          <span>Total: {stats?.total || scanHistory.length}</span>
        </div>
        <div className="stat-pill dangerous">
          <AlertTriangle size={16} />
          <span>Dangerous: {stats?.dangerous || 0}</span>
        </div>
        <div className="stat-pill suspicious">
          <Shield size={16} />
          <span>Suspicious: {stats?.suspicious || 0}</span>
        </div>
        <div className="stat-pill safe">
          <CheckCircle size={16} />
          <span>Safe: {stats?.safe || 0}</span>
        </div>
      </div>

      <div className="filters-bar">
        <div className="search-box">
          <Search size={18} />
          <input
            type="text"
            placeholder="Search URLs..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="filter-group">
          <button className="btn btn-secondary filter-toggle" onClick={() => setShowFilters(!showFilters)}>
            <Filter size={16} />
            <span>Filters</span>
            <ChevronDown size={16} />
          </button>
          {showFilters && (
            <div className="filter-dropdown">
              <label>
                <input
                  type="radio"
                  name="verdict"
                  checked={!verdictFilter}
                  onChange={() => setVerdictFilter('')}
                />
                All
              </label>
              <label>
                <input
                  type="radio"
                  name="verdict"
                  checked={verdictFilter === 'dangerous'}
                  onChange={() => setVerdictFilter('dangerous')}
                />
                Dangerous
              </label>
              <label>
                <input
                  type="radio"
                  name="verdict"
                  checked={verdictFilter === 'suspicious'}
                  onChange={() => setVerdictFilter('suspicious')}
                />
                Suspicious
              </label>
              <label>
                <input
                  type="radio"
                  name="verdict"
                  checked={verdictFilter === 'safe'}
                  onChange={() => setVerdictFilter('safe')}
                />
                Safe
              </label>
            </div>
          )}
        </div>
      </div>

      <div className="scans-table-container">
        {isLoading && scanHistory.length === 0 ? (
          <div className="loading-state">
            <Loader2 size={32} className="spinner" />
            <p>Loading scans...</p>
          </div>
        ) : scanHistory.length === 0 ? (
          <div className="empty-state">
            <Shield size={48} />
            <h3>No scans found</h3>
            <p>{searchQuery || verdictFilter ? 'Try adjusting your filters' : 'Scan your first URL to get started'}</p>
            {!searchQuery && !verdictFilter && (
              <Link to="/dashboard" className="btn btn-primary">
                <Shield size={16} /> Scan a URL
              </Link>
            )}
          </div>
        ) : (
          <>
            <table className="scans-table" role="table">
              <thead>
                <tr>
                  <th>Verdict</th>
                  <th>URL</th>
                  <th>Risk Score</th>
                  <th>Scanned</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {scanHistory
                  .filter(scan => !searchQuery || scan.url.toLowerCase().includes(searchQuery.toLowerCase()))
                  .map(scan => (
                    <tr key={scan.id}>
                      <td>
                        <span className={`verdict-badge ${getVerdictClass(scan.verdict)}`}>
                          {getVerdictIcon(scan.verdict)}
                          {scan.verdict}
                        </span>
                      </td>
                      <td>
                        <Link to={`/scans/${scan.id}`} className="url-link" title={scan.url}>
                          {scan.url}
                        </Link>
                      </td>
                      <td>
                        <div className="risk-score-cell">
                          <span className="risk-score" style={{ color: getVerdictClass(scan.verdict) === 'safe' ? 'var(--accent-green)' : getVerdictClass(scan.verdict) === 'dangerous' ? 'var(--accent-red)' : 'var(--accent-yellow)' }}>
                            {scan.risk_score}/10
                          </span>
                          <div className="risk-bar">
                            <div className="risk-bar-fill" style={{ width: `${scan.risk_score * 10}%` }} />
                          </div>
                        </div>
                      </td>
                      <td className="scan-time">{formatDistanceToNow(new Date(scan.created_at), { addSuffix: true })}</td>
                      <td>
                        <div className="action-buttons">
                          <Link to={`/scans/${scan.id}`} className="btn-icon" title="View details">
                            <ExternalLink size={16} />
                          </Link>
                          <button className="btn-icon danger" onClick={() => handleDelete(scan.id)} title="Delete">
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
              </tbody>
            </table>

            <div className="pagination">
              <button className="btn btn-secondary" disabled={page === 1} onClick={() => setPage(p => p - 1)}>Previous</button>
              <span className="page-info">Page {page}</span>
              <button className="btn btn-secondary" disabled={scanHistory.length < perPage} onClick={() => setPage(p => p + 1)}>Next</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}