import { create } from 'zustand';

export const useOrgStore = create((set, get) => ({
  currentOrg: null,
  orgs: [],
  orgMembers: [],
  orgActivity: [],
  orgStats: null,
  isLoading: false,
  error: null,

  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),

  loadOrgs: async (params = {}) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.organizations.list(params);
      set({ orgs: data.organizations, isLoading: false });
      return data;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  loadOrg: async (id) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const data = await api.organizations.get(id);
      set({ currentOrg: data.organization, isLoading: false });
      return data.organization;
    } catch (e) {
      set({ error: e.message, isLoading: false });
    }
  },

  createOrg: async (data) => {
    set({ isLoading: true });
    try {
      const { api } = require('../services/api');
      const result = await api.organizations.create(data);
      set(state => ({ orgs: [result.organization, ...state.orgs], isLoading: false }));
      return result;
    } catch (e) {
      set({ error: e.message, isLoading: false });
      throw e;
    }
  },

  updateOrg: async (id, data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.organizations.update(id, data);
      set(state => ({
        orgs: state.orgs.map(o => o.id === id ? result.organization : o),
        currentOrg: state.currentOrg?.id === id ? result.organization : state.currentOrg
      }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  deleteOrg: async (id) => {
    try {
      const { api } = require('../services/api');
      await api.organizations.delete(id);
      set(state => ({ orgs: state.orgs.filter(o => o.id !== id) }));
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadMembers: async (orgId) => {
    try {
      const { api } = require('../services/api');
      const data = await api.organizations.members.list(orgId);
      set({ orgMembers: data.members });
      return data;
    } catch (e) {
      set({ error: e.message });
    }
  },

  addMember: async (orgId, data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.organizations.members.add(orgId, data);
      set(state => ({ orgMembers: [...state.orgMembers, result.membership] }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  updateMember: async (orgId, userId, data) => {
    try {
      const { api } = require('../services/api');
      const result = await api.organizations.members.update(orgId, userId, data);
      set(state => ({
        orgMembers: state.orgMembers.map(m => m.user_id === userId ? result.membership : m)
      }));
      return result;
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  removeMember: async (orgId, userId) => {
    try {
      const { api } = require('../services/api');
      await api.organizations.members.remove(orgId, userId);
      set(state => ({ orgMembers: state.orgMembers.filter(m => m.user_id !== userId) }));
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadSettings: async (orgId) => {
    try {
      const { api } = require('../services/api');
      return await api.organizations.settings.get(orgId);
    } catch (e) {
      set({ error: e.message });
    }
  },

  updateSettings: async (orgId, data) => {
    try {
      const { api } = require('../services/api');
      return await api.organizations.settings.update(orgId, data);
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadSSO: async (orgId) => {
    try {
      const { api } = require('../services/api');
      return await api.organizations.sso.get(orgId);
    } catch (e) {
      set({ error: e.message });
    }
  },

  configureSSO: async (orgId, data) => {
    try {
      const { api } = require('../services/api');
      return await api.organizations.sso.configure(orgId, data);
    } catch (e) {
      set({ error: e.message });
      throw e;
    }
  },

  disableSSO: async (orgId) => {
    try {
      const { api } = require('../services/api');
      return await api.organizations.sso.disable(orgId);
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadActivity: async (orgId, params = {}) => {
    try {
      const { api } = require('../services/api');
      const data = await api.organizations.activity(orgId, params);
      set({ orgActivity: data.activity });
      return data;
    } catch (e) {
      set({ error: e.message });
    }
  },

  loadStats: async (orgId) => {
    try {
      const { api } = require('../services/api');
      const data = await api.organizations.stats(orgId);
      set({ orgStats: data });
      return data;
    } catch (e) {
      set({ error: e.message });
    }
  }
}));